-- =============================================================================
-- 476 — LE CAHIER D'EXERCICES DE 5E (partie 5)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/5e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 476 --niveau 5e --fichiers histoire-geo.n2,latin.n1,maths.n1,maths.n2 --suffixe 5 > supabase/contenu/476_exercices_5e_5.sql
--
-- 93 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.n2         30 exercices · 10 chapitres
--   latin.n1                 9 exercices · 3 chapitres
--   maths.n1                27 exercices · 9 chapitres
--   maths.n2                27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('445027f4-5377-5bdc-9603-a8f5af992480'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une frise de Luther à Henri IV","competence":"se-reperer-temps","situation":"Mathis prépare un exposé sur les guerres de Religion. Il place sur une frise les dates à retenir, du moment où Luther critique l’Église jusqu’à l’édit de Nantes.","documents":[{"id":"frise","type":"frise","titre":"Les conflits religieux, de 1510 à 1600","source":"Dates du cours.","debut":1510,"fin":1600,"pas":10,"evenements":[{"id":"z1","date":1517,"nom":"95 thèses"},{"id":"z2","date":1562,"nom":"Début des guerres"},{"id":"z3","date":1572,"nom":"Saint-Barthélemy"},{"id":"z4","date":1589,"nom":"Henri IV roi"},{"id":"z5","date":1593,"nom":"Conversion"},{"id":"z6","date":1598,"nom":"Édit de Nantes"}]}],"questions":[{"enonce":"Touche l’événement de **1572**.","aide":"Cherche la graduation de 1570, puis avance de deux ans.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le début des guerres de Religion de l’édit de Nantes ?","aide":"Soustrais la date de début à la date de l’édit.","type":"nombre","unite":"ans"},{"enonce":"Quel événement a lieu entre l’arrivée d’Henri IV sur le trône et l’édit de Nantes ?","aide":"Henri IV devient roi en 1589 et l’édit est de 1598 : cherche une date entre les deux.","type":"choix","options":[{"id":"a","texte":"Le début des guerres de Religion"},{"id":"b","texte":"Le massacre de la Saint-Barthélemy"},{"id":"c","texte":"La publication des 95 thèses"},{"id":"d","texte":"Sa conversion au catholicisme"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"En **1572**, le massacre de la Saint-Barthélemy tue plusieurs milliers de protestants à Paris et en province."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 ans","explication":"1598 − 1562 = **36** : la guerre civile dure trente-six ans, et l’édit de Nantes y met fin."},{"cle":{"type":"choix","ids":["d"]},"explication":"Henri IV se convertit en **1593**, entre 1589 et 1598 : les trois autres événements sont antérieurs à son règne."}]$ex$::jsonb),
  ('445027f4-5377-5bdc-9603-a8f5af992480'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois croyants, trois façons de croire","competence":"analyser-texte","situation":"Au XVIe siècle, l’Europe se divise en plusieurs Églises. Trois personnages imaginés racontent leur façon de pratiquer : un luthérien, une calviniste et un jésuite catholique.","documents":[{"id":"temoins","type":"texte","genre":"article","titre":"Trois témoignages","auteur":"Témoignages imaginés pour l’exercice.","blocs":["**Hans, marchand à Wittenberg, 1530.** « Notre pasteur s’est marié l’an dernier et personne ne s’en étonne. Chez nous, tout le monde lit la Bible en allemand, car elle seule fait autorité en matière de foi. Nous ne gardons que deux sacrements : le baptême et l’eucharistie. »","**Jeanne, drapière réfugiée à Genève, 1555.** « Ici, le temple est nu : ni statues ni décors. Notre pasteur répète que Dieu a choisi d’avance ceux qui seront sauvés. Pour nous aussi, seule la Bible fait autorité. »","**Père Antoine, jésuite, 1575.** « J’enseigne dans un collège et je prépare mon départ en mission. Nos prêtres sont désormais formés dans des séminaires, comme l’a décidé le concile de Trente. Rome publie aussi la liste des livres interdits : l’Index. »"]}],"questions":[{"enonce":"Associe chaque personnage à sa confession.","aide":"Cherche dans chaque témoignage le lieu et les pratiques décrites.","type":"association","gauche":[{"id":"g0","texte":"Hans, à Wittenberg"},{"id":"g1","texte":"Jeanne, à Genève"},{"id":"g2","texte":"Père Antoine"}],"droite":[{"id":"d0","texte":"Luthérien"},{"id":"d1","texte":"Jésuite catholique"},{"id":"d2","texte":"Calviniste"}]},{"enonce":"Touche le mot du témoignage de Jeanne qui exprime la **prédestination**.","aide":"La prédestination, c’est l’idée que Dieu décide à l’avance : cherche le verbe de cette décision.","type":"zone","document":"temoins","multiple":false},{"enonce":"Quel point commun les témoignages de Hans et de Jeanne montrent-ils ?","aide":"Relis la phrase sur la Bible dans chacun des deux témoignages.","type":"choix","options":[{"id":"a","texte":"Ils pensent que Dieu n’a rien décidé d’avance pour personne"},{"id":"b","texte":"Ils gardent les sept sacrements de l’Église catholique"},{"id":"c","texte":"Pour eux, la Bible est la seule autorité en matière de foi"},{"id":"d","texte":"Ils obéissent au pape et à la liste des livres interdits"}],"multiple":false},{"enonce":"Complète la phrase à partir du témoignage du père Antoine.","aide":"Le père Antoine cite le concile et le lieu de formation des prêtres.","type":"trous","segments":["Le concile de ",0," a décidé que les prêtres seraient formés dans des ",1,"."],"banque":["séminaires","Genève","monastères","Trente"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Hans est **luthérien** (Wittenberg, pasteur marié, deux sacrements), Jeanne est **calviniste** (Genève, prédestination), le père Antoine est un **jésuite catholique** (concile de Trente, Index)."},{"cle":{"type":"zone","ids":["m70"]},"explication":"Pour les calvinistes, Dieu a **choisi** d’avance ceux qui seront sauvés : c’est la prédestination."},{"cle":{"type":"choix","ids":["c"]},"explication":"Luthériens et calvinistes sont protestants : ils s’appuient sur la **Bible seule**, et non sur l’autorité de Rome."},{"cle":{"type":"trous","trous":[["trente"],["seminaires","seminaire"]]},"affichage":"Trente · séminaires","explication":"Le concile de **Trente** (1545-1563) réaffirme les dogmes et crée les **séminaires** : c’est la réaction catholique."}]$ex$::jsonb),
  ('445027f4-5377-5bdc-9603-a8f5af992480'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"De Genève aux Pays-Bas, puis l’édit de Nantes","competence":"lire-carte","situation":"Zoé suit la route des idées de Luther et de Calvin sur une carte de l’Europe. Puis elle lit un résumé de l’édit de Nantes, qui met fin à trente-six ans de guerre civile.","documents":[{"id":"carte","type":"carte","titre":"Quelques villes de la Réforme","fond":"europe","frontieres":true,"cadrage":[-8,44,16,58],"source":"Villes citées dans le cours.","lieux":[{"id":"z1","lon":12.65,"lat":51.87,"nom":"Wittenberg","symbole":"point","teinte":"violet"},{"id":"z2","lieu":"geneve","nom":"Genève","symbole":"point","teinte":"violet"},{"id":"z3","lieu":"paris","nom":"Paris","symbole":"point","teinte":"violet"},{"id":"z4","lieu":"edimbourg","nom":"Édimbourg","symbole":"point","teinte":"violet"},{"id":"z5","lieu":"amsterdam","nom":"Amsterdam","symbole":"point","teinte":"violet"}]},{"id":"edit","type":"texte","genre":"article","titre":"L’édit de Nantes, en résumé","auteur":"Résumé écrit pour l’exercice : ce n’est pas le texte de l’édit.","blocs":["Après trente-six ans de guerre civile, le roi Henri IV veut ramener la paix dans le royaume.","Il accorde aux protestants la liberté de conscience : personne ne peut être poursuivi pour sa foi.","Leur culte est autorisé, mais seulement dans certains lieux fixés par l’édit.","Ils gardent aussi des places de sûreté, des villes fortes où ils peuvent se défendre.","En 1685, Louis XIV révoquera l’édit."]}],"questions":[{"enonce":"Touche la ville où Calvin développe sa doctrine.","aide":"Calvin s’y est réfugié ; la ville est située au sud-est de la France, près des Alpes.","type":"zone","document":"carte","multiple":false},{"enonce":"Depuis Genève, le calvinisme gagne la France, l’Écosse et les Pays-Bas. Touche les **trois villes** de la carte qui se trouvent dans ces pays.","aide":"Écarte Wittenberg (Allemagne) et Genève (Suisse) : il reste trois villes.","type":"zone","document":"carte","multiple":true},{"enonce":"Touche les deux mots qui montrent que le culte protestant reste **encadré**.","aide":"Cherche dans le troisième paragraphe les mots qui limitent les endroits où l’on peut prier.","type":"zone","document":"edit","multiple":true},{"enonce":"Pendant combien d’années l’édit de Nantes (1598) est-il resté en vigueur avant sa révocation ?","aide":"Le résumé donne l’année de la révocation ; soustrais 1598.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi Henri IV signe-t-il l’édit de Nantes ?","aide":"Relis le premier paragraphe du résumé : que veut le roi après trente-six ans de guerre ?","type":"choix","options":[{"id":"a","texte":"Pour proclamer la tolérance religieuse au sens moderne"},{"id":"b","texte":"Pour arrêter la guerre en organisant la coexistence des deux religions"},{"id":"c","texte":"Pour interdire le protestantisme dans tout le royaume"},{"id":"d","texte":"Pour rendre les protestants plus nombreux que les catholiques"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Calvin développe sa doctrine à **Genève**, qui devient une cité strictement réglée."},{"cle":{"type":"zone","ids":["z3","z4","z5"]},"explication":"**Paris** (France), **Édimbourg** (Écosse) et **Amsterdam** (Pays-Bas) sont dans les trois pays gagnés par le calvinisme."},{"cle":{"type":"zone","ids":["m40","m41"]},"explication":"Le culte n’est autorisé que dans **certains lieux** : l’édit organise une coexistence, pas une liberté totale."},{"cle":{"type":"nombre","valeur":87,"tolerance":0},"affichage":"87 ans","explication":"1685 − 1598 = **87** ans : Louis XIV révoque l’édit en 1685."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’édit **ne proclame pas la tolérance moderne** : il organise une **coexistence** pour mettre fin à la guerre civile."}]$ex$::jsonb),
  ('a2ec4edc-e919-54ad-be52-a5e38bcf152e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Du roi Henri IV au Roi-Soleil","competence":"se-reperer-temps","situation":"Camille veut comprendre comment le pouvoir du roi s’est renforcé. Elle trace une frise de 1580 à 1720 avec deux règnes et quelques dates clés.","documents":[{"id":"frise","type":"frise","titre":"Vers la monarchie absolue","source":"Dates du cours.","debut":1580,"fin":1720,"pas":20,"periodes":[{"id":"z1","debut":1589,"fin":1610,"nom":"Henri IV","teinte":"ambre"},{"id":"z2","debut":1661,"fin":1715,"nom":"Règne personnel de Louis XIV","teinte":"turquoise"}],"evenements":[{"id":"z3","date":1624,"nom":"Richelieu"},{"id":"z4","date":1648,"nom":"La Fronde"},{"id":"z5","date":1661,"nom":"Louis XIV seul"},{"id":"z6","date":1682,"nom":"Cour à Versailles"},{"id":"z7","date":1685,"nom":"Révocation"}]}],"questions":[{"enonce":"Touche l’événement qui fixe la cour à **Versailles**.","aide":"Cherche l’événement qui porte le nom de Versailles, vers la fin du règne.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la Fronde du moment où Louis XIV décide de gouverner seul ?","aide":"Lis les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Quel événement a lieu avant le règne personnel de Louis XIV ?","aide":"Le règne personnel commence en 1661 : cherche une date plus ancienne.","type":"choix","options":[{"id":"a","texte":"L’installation de la cour à Versailles"},{"id":"b","texte":"La révocation de l’édit de Nantes"},{"id":"c","texte":"La Fronde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z6"]},"explication":"La cour est fixée à **Versailles** en 1682 : la noblesse y vit sous les yeux du roi."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 ans","explication":"1661 − 1648 = **13** ans : le jeune roi garde de la Fronde un souvenir durable avant de gouverner seul."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **Fronde** (1648-1653) précède 1661 ; Versailles (1682) et la révocation (1685) viennent après."}]$ex$::jsonb),
  ('a2ec4edc-e919-54ad-be52-a5e38bcf152e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre écrite depuis Versailles","competence":"analyser-texte","situation":"En 1683, un gentilhomme installé à la cour écrit à son cousin resté sur ses terres. Sa lettre montre ce que Versailles change dans la vie de la noblesse.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Versailles, 1683","auteur":"Lettre imaginée pour l’exercice.","blocs":["Cher cousin,","Depuis que le roi a fixé la cour ici, je n’ai plus une journée à moi. Dès le matin, il faut assister à son lever, puis suivre l’étiquette : chacun a sa place, son tour, son geste.","Je n’ai plus le temps de visiter mes terres. Pour obtenir une charge ou une pension, je dépends de la faveur du roi.","Hier encore, une fête magnifique : des portraits, des artistes pensionnés, des feux d’artifice. Tout parle de la gloire du Roi-Soleil."]}],"questions":[{"enonce":"Touche le mot qui désigne les règles strictes de la cour.","aide":"Cherche le mot qui annonce « chacun a sa place, son tour, son geste ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Selon la lettre, pourquoi le gentilhomme ne peut-il plus agir en seigneur indépendant ?","aide":"Relis les deux premiers paragraphes : que fait-il toute la journée, et de qui dépend-il ?","type":"choix","options":[{"id":"a","texte":"Il doit rester chez lui pour surveiller ses paysans"},{"id":"b","texte":"Il passe ses journées à la cour et dépend des faveurs du roi"},{"id":"c","texte":"Il est devenu ministre et gère les finances du royaume"},{"id":"d","texte":"Il a perdu toutes ses terres à cause de la Fronde"}],"multiple":false},{"enonce":"Classe ces moyens de gouverner de Louis XIV selon leur but.","aide":"Demande-toi : cela occupe-t-il les nobles, cela célèbre-t-il le roi, ou cela produit-il de la richesse et de la force ?","type":"categories","categories":[{"id":"c0","texte":"Dominer la noblesse"},{"id":"c1","texte":"Faire briller le Roi-Soleil"},{"id":"c2","texte":"Enrichir et défendre le royaume"}],"items":[{"id":"i0","texte":"Entretenir une armée permanente"},{"id":"i1","texte":"Créer des manufactures royales"},{"id":"i2","texte":"Imposer l’étiquette"},{"id":"i3","texte":"Pensionner des artistes"},{"id":"i4","texte":"Fixer la cour à Versailles"},{"id":"i5","texte":"Commander des portraits et des fêtes"}]},{"enonce":"Que cherchent à montrer les fêtes, les portraits et les artistes dont parle le gentilhomme ?","aide":"Relis la dernière phrase de la lettre.","type":"choix","options":[{"id":"a","texte":"La pauvreté du royaume après les famines"},{"id":"b","texte":"La grandeur du roi, présenté comme le Roi-Soleil"},{"id":"c","texte":"Le pouvoir des nobles face au roi"},{"id":"d","texte":"La victoire des protestants sur les catholiques"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31"]},"explication":"L’**étiquette** fixe la place et les gestes de chacun : elle occupe la noblesse du matin au soir."},{"cle":{"type":"choix","ids":["b"]},"explication":"Retenue à Versailles, la noblesse est **domestiquée** : elle dépend du roi pour les charges et les pensions."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Versailles et l’étiquette **dominent la noblesse** ; portraits, fêtes et artistes **font briller le Roi-Soleil** ; les manufactures de Colbert et l’armée **enrichissent et défendent** le royaume."},{"cle":{"type":"choix","ids":["b"]},"explication":"Portraits, fêtes et académies construisent l’**image** du roi : le Roi-Soleil, au centre d’un royaume qu’il gouverne seul."}]$ex$::jsonb),
  ('a2ec4edc-e919-54ad-be52-a5e38bcf152e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un tisserand quitte le royaume","competence":"analyser-document","situation":"En 1686, un maître tisserand protestant décide de fuir la France, un an après la révocation de l’édit de Nantes. Théo lit sa lettre, puis replace cet événement dans la fin du règne de Louis XIV.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un tisserand, 1686","auteur":"Lettre imaginée pour l’exercice.","blocs":["Depuis la révocation de l’édit de Nantes, l’an dernier, notre temple est fermé et nos pasteurs sont partis. On nous demande de nous convertir.","Je dirige un atelier de douze ouvriers et je forme des apprentis. Le roi interdit de quitter le royaume, mais nous partirons de nuit pour la Hollande, avec nos outils et tout ce que nous savons faire."]},{"id":"frise","type":"frise","titre":"La fin du règne personnel de Louis XIV","source":"Dates du cours.","debut":1660,"fin":1720,"pas":10,"periodes":[{"id":"z1","debut":1661,"fin":1715,"nom":"Règne personnel","teinte":"turquoise"}],"evenements":[{"id":"z2","date":1685,"nom":"Révocation"},{"id":"z3","date":1693,"nom":"Famine"},{"id":"z4","date":1709,"nom":"Famine"},{"id":"z5","date":1715,"nom":"Mort du roi"}]}],"questions":[{"enonce":"Combien d’années séparent la révocation de l’édit de Nantes de la première famine ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Touche les **trois mots** qui montrent que le tisserand emploie et forme du monde.","aide":"Cherche l’endroit où il travaille et les personnes qui travaillent avec lui.","type":"zone","document":"lettre","multiple":true},{"enonce":"Pourquoi le départ de milliers de protestants comme lui est-il un désastre économique ?","aide":"Pense à ce que l’atelier du tisserand produisait et à ce qu’il emporte en partant.","type":"choix","options":[{"id":"a","texte":"Ils étaient trop nombreux et le royaume manquait de logements pour tous"},{"id":"b","texte":"Beaucoup étaient des artisans qualifiés qui emportaient leur savoir-faire"},{"id":"c","texte":"Ils construisaient eux-mêmes des forteresses pour le compte du roi"},{"id":"d","texte":"Ils refusaient de payer l’impôt et de faire vivre les villes du royaume"}],"multiple":false},{"enonce":"Un roi absolu n’est pas libre de tout : il est tenu par les lois fondamentales du royaume. Classe ces actions.","aide":"Souviens-toi : absolu ne veut pas dire arbitraire. Les lois fondamentales protègent la succession et le domaine.","type":"categories","categories":[{"id":"c0","texte":"Le roi peut"},{"id":"c1","texte":"Le roi ne peut pas"}],"items":[{"id":"i0","texte":"Vendre ou donner le domaine royal"},{"id":"i1","texte":"Changer l’ordre de succession"},{"id":"i2","texte":"Faire les lois"},{"id":"i3","texte":"Rendre la justice"},{"id":"i4","texte":"Choisir ses ministres"}]},{"enonce":"Que laissent en 1715, d’après la frise, les dernières années du règne ?","aide":"Regarde les événements placés entre 1685 et 1715 sur la frise.","type":"choix","options":[{"id":"a","texte":"Une paix durable qui rétablit les finances du royaume"},{"id":"b","texte":"Des famines et des guerres coûteuses laissent un royaume affaibli"},{"id":"c","texte":"Un royaume enrichi par le retour des protestants"},{"id":"d","texte":"Un roi dont le pouvoir est limité par des assemblées élues"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 ans","explication":"1693 − 1685 = **8** ans : les famines s’ajoutent aux guerres et aux difficultés du royaume."},{"cle":{"type":"zone","ids":["m29","m32","m37"]},"explication":"Un **atelier**, des **ouvriers**, des **apprentis** : un artisan qualifié qui emporte avec lui son savoir-faire."},{"cle":{"type":"choix","ids":["b"]},"explication":"La révocation chasse **des dizaines de milliers de protestants**, souvent artisans et commerçants qualifiés : c’est un désastre économique autant qu’humain."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"Le roi réunit les pouvoirs, mais il **ne peut ni changer l’ordre de succession ni aliéner le domaine royal**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les famines de **1693 et 1709**, s’ajoutant aux guerres et aux finances épuisées, laissent à la mort du roi un royaume affaibli."}]$ex$::jsonb),
  ('e9026b5d-4908-5eaf-9eb1-22885e5f9dbc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les trois piliers du développement durable","competence":"observer-schema","situation":"Sa classe prépare une affiche sur le développement durable. Maëlle dessine les trois piliers sous la forme de trois cercles qui se recouvrent.","documents":[{"id":"piliers","type":"schema","titre":"Les trois piliers","largeur":360,"hauteur":340,"source":"Schéma du cours.","elements":[{"forme":"cercle","cx":180,"cy":120,"r":80,"teinte":"jaune","motif":"aucun","id":"z1","zone":true},{"forme":"cercle","cx":130,"cy":210,"r":80,"teinte":"rose","motif":"aucun","id":"z2","zone":true},{"forme":"cercle","cx":230,"cy":210,"r":80,"teinte":"vert","motif":"aucun","id":"z3","zone":true},{"forme":"ellipse","cx":180,"cy":180,"rx":24,"ry":20,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":180,"y":20,"texte":"Économique","gras":true,"ancre":"milieu"},{"forme":"texte","x":60,"y":322,"texte":"Social","gras":true,"ancre":"milieu"},{"forme":"texte","x":275,"y":322,"texte":"Environnemental","gras":true,"ancre":"milieu"}]}],"questions":[{"enonce":"Touche le pilier qui concerne la **santé**, l’**éducation** et le **logement** pour tous.","aide":"Trois piliers : économique, social, environnemental. Lequel parle des personnes ?","type":"zone","document":"piliers","multiple":false},{"enonce":"Touche la zone où les **trois piliers** se croisent : c’est là qu’un projet est durable.","aide":"Cherche la zone qui se trouve à l’intérieur des trois cercles à la fois.","type":"zone","document":"piliers","multiple":false},{"enonce":"Un projet crée beaucoup d’emplois, mais pollue la rivière du village. Combien de piliers respecte-t-il ?","aide":"Les emplois relèvent du pilier économique. Que dit la pollution sur le pilier environnemental ?","type":"choix","options":[{"id":"a","texte":"Deux : il est durable"},{"id":"b","texte":"Les trois : il est durable"},{"id":"c","texte":"Aucun des trois piliers"},{"id":"d","texte":"Un seul : il n’est pas durable"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le pilier **social** demande santé, éducation, logement et équité pour tous."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Un projet n’est **durable** que s’il satisfait les **trois piliers à la fois** : c’est la zone du centre."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il ne respecte que le pilier **économique** : sans le social et l’environnemental, il n’est **pas durable**."}]$ex$::jsonb),
  ('e9026b5d-4908-5eaf-9eb1-22885e5f9dbc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quel projet pour la commune de Port-Clair ?","competence":"lire-tableau","situation":"Le maire de Port-Clair, ville imaginée, hésite entre quatre projets. Il les passe au crible des trois piliers du développement durable : emplois, bénéfice pour tous, respect de l’environnement.","documents":[{"id":"projets","type":"tableau","titre":"Quatre projets pour la commune","source":"Projets imaginés pour l’exercice.","colonnes":["Projet","Crée des emplois","Profite à tous les habitants","Préserve l’environnement"],"lignes":[["A. Une usine qui rejette ses déchets dans la rivière","Oui","Non","Non"],["B. Une réserve naturelle entièrement clôturée","Non","Non","Oui"],["C. Un quartier de logements avec tramway et énergie solaire","Oui","Oui","Oui"],["D. Un parc solaire dont l’électricité est trop chère pour les habitants","Oui","Non","Oui"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le projet qui respecte les **trois piliers**.","aide":"Cherche la ligne où il n’y a que des « Oui ».","type":"zone","document":"projets","multiple":false},{"enonce":"Touche le projet qui est **viable** (économie + environnement) mais pas **équitable**.","aide":"Viable = emplois ET environnement. Équitable = emplois ET profit pour tous. Cherche « Oui », « Non », « Oui ».","type":"zone","document":"projets","multiple":false},{"enonce":"Que faut-il changer pour que le projet D devienne durable ?","aide":"Quel pilier est « Non » pour le projet D ?","type":"choix","options":[{"id":"a","texte":"Cesser de préserver l’environnement autour du parc"},{"id":"b","texte":"Baisser le prix de l’électricité pour que tous en profitent"},{"id":"c","texte":"Supprimer les emplois qu’il a créés dans la commune"},{"id":"d","texte":"Installer d’autres panneaux sans changer le prix de vente"}],"multiple":false},{"enonce":"Le développement durable se joue à toutes les échelles. Range ces actions du plus local au plus mondial.","aide":"Pars du collège, passe à la ville, finis par le monde.","type":"ordre","items":[{"id":"a","texte":"Un accord climatique mondial"},{"id":"b","texte":"Une piste cyclable dans une ville"},{"id":"c","texte":"Un tri sélectif dans un collège"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le projet **C** coche les trois colonnes : économique, social et environnemental. C’est le seul durable."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le projet **D** crée des emplois et préserve l’environnement (viable), mais l’électricité est trop chère pour les habitants : il n’est pas équitable."},{"cle":{"type":"choix","ids":["b"]},"explication":"Il manque le pilier **social** : en rendant l’électricité accessible à tous, le projet D satisferait les trois piliers."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"Du **local** au **mondial** : le collège, la ville, puis l’accord entre États. Les échelles se répondent."}]$ex$::jsonb),
  ('e9026b5d-4908-5eaf-9eb1-22885e5f9dbc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"PIB, IDH et empreinte : comparer quatre pays","competence":"analyser-document","situation":"Pour son exposé, Ismaël compare quatre pays imaginés avec trois indicateurs, puis place sur une frise les grandes étapes qui ont conduit à parler de développement durable.","documents":[{"id":"frise","type":"frise","titre":"Du premier sommet de la Terre aux objectifs de 2030","source":"Dates du cours.","debut":1970,"fin":2030,"pas":10,"evenements":[{"id":"z1","date":1972,"nom":"Stockholm"},{"id":"z2","date":1987,"nom":"Rapport Brundtland"},{"id":"z3","date":1992,"nom":"Sommet de Rio"},{"id":"z4","date":2015,"nom":"17 objectifs"},{"id":"z5","date":2030,"nom":"Échéance"}]},{"id":"pays","type":"tableau","titre":"Quatre pays comparés","source":"Pays et chiffres imaginés pour l’exercice.","colonnes":["Pays","PIB par habitant ($)","IDH","Empreinte (planètes)"],"lignes":[["A","60 000","0,95","4,0"],["B","12 000","0,80","1,8"],["C","2 000","0,50","0,8"],["D","24 000","0,76","2,6"]],"enteteLignes":true}],"questions":[{"enonce":"Combien d’années séparent le premier sommet de la Terre de celui de Rio ?","aide":"Lis les dates de Stockholm et de Rio sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Le pays D a un PIB par habitant deux fois plus élevé que le pays B, mais un IDH plus faible. Que montre cet écart ?","aide":"Compare le PIB et l’IDH des pays B et D.","type":"choix","options":[{"id":"a","texte":"L’IDH ne dépend pas de l’éducation ni de la santé"},{"id":"b","texte":"Plus un pays est riche, plus son IDH est élevé"},{"id":"c","texte":"Le PIB par habitant ne suffit pas à mesurer le développement"},{"id":"d","texte":"Le PIB par habitant mesure à lui seul le développement"}],"multiple":false},{"enonce":"Combien de fois l’empreinte écologique du pays A est-elle plus grande que celle du pays C ?","aide":"Divise l’empreinte de A par celle de C.","type":"nombre","unite":"fois"},{"enonce":"Touche l’IDH du pays dont l’**empreinte écologique** est la plus lourde.","aide":"Repère d’abord la plus grande empreinte, puis lis l’IDH sur la même ligne.","type":"zone","document":"pays","multiple":false},{"enonce":"Pourquoi le pays A ne peut-il pas servir de modèle de développement durable pour tous ?","aide":"Regarde la colonne « Empreinte (planètes) ».","type":"choix","options":[{"id":"a","texte":"Son PIB par habitant est trop bas pour créer des emplois"},{"id":"b","texte":"Son empreinte est inférieure à celle de la planète"},{"id":"c","texte":"Son IDH est trop faible pour offrir une bonne éducation"},{"id":"d","texte":"Si toute l’humanité vivait comme lui, il faudrait quatre planètes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 ans","explication":"1992 − 1972 = **20** ans entre le premier sommet de la Terre et celui de Rio, où le terme se popularise."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’IDH combine **richesse, espérance de vie et éducation** : un pays plus riche peut avoir un IDH plus faible. Le PIB par habitant ne suffit pas."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 fois","explication":"4,0 ÷ 0,8 = **5** : l’empreinte du pays A est cinq fois plus lourde que celle du pays C."},{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Le pays **A** a l’empreinte la plus lourde (4,0) et un IDH de **0,95**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec une empreinte de **4,0 planètes**, ce mode de vie n’est pas généralisable : le développement durable est né de ce constat."}]$ex$::jsonb),
  ('ec7397cc-48b8-5347-ba45-a9bc9806dc43'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un milliard de plus, de plus en plus vite","competence":"lire-graphique","situation":"Inès veut comprendre pourquoi on parle d’une croissance sans précédent. Elle lit un graphique qui donne l’année où la Terre atteint chaque milliard d’habitants.","documents":[{"id":"pop","type":"graphique","forme":"barres","titre":"L’année où l’humanité atteint chaque milliard","source":"Chiffres arrondis, d’après l’ONU.","categories":["Vers 1800","1927","1960","1974","1987","1999","2011","2022"],"series":[{"nom":"Population mondiale","valeurs":[1,2,3,4,5,6,7,8],"teinte":"turquoise"}],"axeY":{"titre":"Population mondiale","unite":"milliards","min":0,"max":8,"pas":1},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Touche l’année où l’humanité atteint **8 milliards** d’habitants.","aide":"C’est la barre la plus haute du graphique.","type":"zone","document":"pop","multiple":false},{"enonce":"Combien d’années faut-il pour passer de 7 à 8 milliards d’habitants ?","aide":"Lis les années des deux dernières barres et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Que remarques-tu sur le temps qu’il faut pour gagner un milliard d’humains de plus ?","aide":"Compare l’écart entre les premières barres et l’écart entre les dernières.","type":"choix","options":[{"id":"a","texte":"Il se raccourcit : de plus d’un siècle à une dizaine d’années"},{"id":"b","texte":"Il s’allonge : de plus en plus de temps est nécessaire"},{"id":"c","texte":"Il reste identique d’un milliard à l’autre"},{"id":"d","texte":"Il disparaît dès que la population dépasse 5 milliards"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k7"]},"explication":"L’humanité atteint 8 milliards en **2022**."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 ans","explication":"2022 − 2011 = **11** ans pour gagner un milliard d’habitants."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il faut plus d’un siècle pour passer de 1 à 2 milliards, mais seulement **11 à 14 ans** pour les derniers : la croissance s’est fortement accélérée."}]$ex$::jsonb),
  ('ec7397cc-48b8-5347-ba45-a9bc9806dc43'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois pays, trois phases de la transition","competence":"lire-tableau","situation":"Yanis étudie trois pays imaginés pour comprendre la transition démographique. Il lit leur taux de natalité, leur taux de mortalité et leur fécondité, puis les classe par phase.","documents":[{"id":"pays","type":"tableau","titre":"Trois pays comparés","source":"Pays et chiffres imaginés pour l’exercice. Les taux sont des naissances ou des décès pour 1 000 habitants par an (‰).","colonnes":["Pays","Natalité (‰)","Mortalité (‰)","Enfants par femme"],"lignes":[["X",38,35,"5,6"],["Y",38,9,"4,9"],["Z",10,9,"1,6"]],"enteteLignes":true}],"questions":[{"enonce":"Calcule l’accroissement naturel du pays Y.","aide":"Accroissement naturel = natalité − mortalité.","type":"nombre","unite":"‰"},{"enonce":"Associe chaque pays à la phase de la transition démographique qu’il traverse.","aide":"Regarde ce que fait la mortalité par rapport à la natalité dans chaque pays.","type":"association","gauche":[{"id":"g0","texte":"Pays X"},{"id":"g1","texte":"Pays Y"},{"id":"g2","texte":"Pays Z"}],"droite":[{"id":"d0","texte":"Phase 1 : la population stagne"},{"id":"d1","texte":"Phase 3 : la population se stabilise"},{"id":"d2","texte":"Phase 2 : la population explose"}]},{"enonce":"Touche la **seule** fécondité qui passe sous le seuil de renouvellement des générations (2,1 enfants par femme).","aide":"Compare chaque valeur de la dernière colonne à 2,1.","type":"zone","document":"pays","multiple":false},{"enonce":"Quel problème le pays Z risque-t-il de rencontrer ?","aide":"Peu de naissances et une mortalité faible : quelle tranche d’âge devient plus nombreuse ?","type":"choix","options":[{"id":"a","texte":"Une explosion de sa population jeune"},{"id":"b","texte":"Un manque d’écoles pour les enfants"},{"id":"c","texte":"Une mortalité qui reste très forte"},{"id":"d","texte":"Le vieillissement de sa population"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":29,"tolerance":0},"affichage":"29 ‰","explication":"38 − 9 = **29 ‰** : la population de Y augmente de 29 personnes pour 1 000 habitants chaque année."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**X** : natalité et mortalité fortes, la population stagne. **Y** : la mortalité a chuté, la natalité reste forte, la population explose. **Z** : les deux sont faibles, la population se stabilise."},{"cle":{"type":"zone","ids":["r2c3"]},"explication":"Seul le pays **Z** est sous 2,1 (1,6 enfant par femme) : les générations ne se renouvellent plus tout à fait."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec peu de naissances et une mortalité faible, la population **vieillit** : c’est le cas des pays du Nord, qui doivent financer les retraites."}]$ex$::jsonb),
  ('ec7397cc-48b8-5347-ba45-a9bc9806dc43'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une jeunesse nombreuse, un village qui vieillit","competence":"lire-carte","situation":"Deux élèves racontent leur quotidien : Mariama à Niamey, au Niger, et Kenji dans un village du Japon. Lana lit leurs récits avec une carte du monde pour comprendre que les défis démographiques ne sont pas les mêmes partout.","documents":[{"id":"carte","type":"carte","titre":"Où vivent les humains ?","fond":"monde","regionsCliquables":true,"cadrage":[-20,-40,160,60],"source":"Fond de carte mondial.","lieux":[{"id":"z1","lieu":"niamey","nom":"Niamey","symbole":"point","teinte":"violet"}]},{"id":"recits","type":"texte","genre":"article","titre":"Deux élèves, deux défis","auteur":"Récits imaginés pour l’exercice.","blocs":["**À Niamey, au Niger.** Mariama, 12 ans, partage sa classe avec soixante élèves. Chaque année, la ville accueille de nouveaux habitants et de nouveaux quartiers sortent de terre, souvent sans routes ni eau courante : l’urbanisation est rapide et difficile à maîtriser.","**Dans un village du Japon.** Kenji, 14 ans, est l’un des rares enfants du village : l’école a fermé il y a deux ans. Sa grand-mère, comme presque tous les habitants, a plus de soixante-dix ans. Le pays se demande comment financer les retraites."]}],"questions":[{"enonce":"Touche les **deux pays** qui comptent plus de 1,4 milliard d’habitants chacun.","aide":"Ils sont tous les deux en Asie : l’un est au nord de l’autre.","type":"zone","document":"carte","multiple":true},{"enonce":"Associe chaque lieu au défi démographique qu’il illustre.","aide":"Dans quel récit les écoles sont-elles pleines ? Dans lequel ferment-elles ?","type":"association","gauche":[{"id":"g0","texte":"Niamey, au Niger"},{"id":"g1","texte":"Un village du Japon"}],"droite":[{"id":"d0","texte":"Financer les retraites d’une population qui vieillit"},{"id":"d1","texte":"Scolariser, loger et soigner une population jeune qui croît vite"}]},{"enonce":"Touche la ville du premier récit.","aide":"Niamey est la capitale du Niger, en Afrique de l’Ouest.","type":"zone","document":"carte","multiple":false},{"enonce":"Pourquoi la même politique démographique ne peut-elle pas convenir au Niger et au Japon ?","aide":"Compare l’âge des habitants dans les deux récits.","type":"choix","options":[{"id":"a","texte":"Les deux pays sont dans la même phase de la transition démographique"},{"id":"b","texte":"L’un doit gérer une jeunesse nombreuse, l’autre une population qui vieillit"},{"id":"c","texte":"Aucun des deux pays ne connaît de problème démographique"},{"id":"d","texte":"Les deux pays comptent plus de 1,4 milliard d’habitants"}],"multiple":false},{"enonce":"Touche le mot du récit qui désigne la croissance rapide des villes.","aide":"Cherche le mot qui parle de la ville qui s’étend et accueille de nouveaux habitants.","type":"zone","document":"recits","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["CHN","IND"]},"explication":"La **Chine** et l’**Inde** dépassent chacune 1,4 milliard d’habitants. L’Asie concentre près de 60 % de l’humanité."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"Au **Sud**, il faut nourrir, loger et scolariser une jeunesse nombreuse ; au **Nord**, le défi est le vieillissement et le financement des retraites."},{"cle":{"type":"zone","ids":["z1"]},"explication":"**Niamey** est dans l’Afrique subsaharienne, une région encore en phase 2 de la transition démographique."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Deux mondes démographiques** coexistent : l’un gère une jeunesse nombreuse, l’autre une population qui vieillit. Ce ne sont pas les mêmes politiques."},{"cle":{"type":"zone","ids":["m35"]},"explication":"L’**urbanisation** est rapide au Sud et souvent mal maîtrisée : manque de logements, de routes, d’eau."}]$ex$::jsonb),
  ('0afccf60-b288-5dbc-a319-d50cfb5c2997'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Développés, émergents ou PMA : où sont-ils ?","competence":"lire-carte","situation":"Nora colorie un planisphère pour repérer trois groupes de pays : les pays développés, les pays émergents et les pays les moins avancés (PMA). Elle n’a coloré que quelques exemples.","documents":[{"id":"carte","type":"carte","titre":"Trois groupes de pays","fond":"monde","regionsCliquables":true,"cadrage":[-125,-40,155,58],"source":"Quelques pays pris pour exemples (cours).","regions":[{"code":"USA","teinte":"bleu"},{"code":"JPN","teinte":"bleu"},{"code":"AUS","teinte":"bleu"},{"code":"CHN","teinte":"ambre"},{"code":"IND","teinte":"ambre"},{"code":"BRA","teinte":"ambre"},{"code":"ZAF","teinte":"ambre"},{"code":"NER","teinte":"corail"},{"code":"TCD","teinte":"corail"},{"code":"MLI","teinte":"corail"},{"code":"ETH","teinte":"corail"},{"code":"COD","teinte":"corail"}],"legende":[{"teinte":"bleu","texte":"Pays développés"},{"teinte":"ambre","texte":"Pays émergents"},{"teinte":"corail","texte":"Pays les moins avancés (PMA)"}]}],"questions":[{"enonce":"Touche le pays **émergent** situé en Afrique.","aide":"Regarde la légende : cherche le groupe des pays émergents, puis celui qui est tout au sud de l’Afrique.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien de pays les moins avancés (PMA) sont coloriés sur la carte ?","aide":"Repère la couleur des PMA dans la légende et compte les pays coloriés ainsi.","type":"nombre"},{"enonce":"Associe chaque pays au groupe auquel il appartient.","aide":"Retrouve la teinte de chaque pays sur la carte, puis cherche-la dans la légende.","type":"association","gauche":[{"id":"g0","texte":"Japon"},{"id":"g1","texte":"Brésil"},{"id":"g2","texte":"Tchad"}],"droite":[{"id":"d0","texte":"Pays émergent"},{"id":"d1","texte":"Pays développé"},{"id":"d2","texte":"Pays les moins avancés (PMA)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["ZAF"]},"explication":"L’**Afrique du Sud** est un pays émergent : croissance rapide, industrialisation et fortes inégalités internes."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"Il y a **5** PMA coloriés : le Niger, le Tchad, le Mali, l’Éthiopie et la République démocratique du Congo. Tous sont en Afrique."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le **Japon** est développé, le **Brésil** est émergent, le **Tchad** est un PMA."}]$ex$::jsonb),
  ('0afccf60-b288-5dbc-a319-d50cfb5c2997'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Même pays, deux adresses : Camille et Davi","competence":"lire-graphique","situation":"Elias compare l’indice de développement humain (IDH) de cinq pays, puis lit le récit de deux enfants qui vivent dans la même grande ville d’un pays émergent.","documents":[{"id":"idh","type":"graphique","forme":"barres","titre":"L’IDH de cinq pays","source":"Chiffres arrondis au centième (PNUD, 2021).","categories":["Norvège","France","Brésil","Inde","Niger"],"series":[{"nom":"IDH","valeurs":[0.96,0.9,0.75,0.63,0.39],"teinte":"violet"}],"axeY":{"titre":"IDH","min":0,"max":1,"pas":0.2},"axeX":{"titre":"Pays"},"valeurs":false},{"id":"recit","type":"texte","genre":"article","titre":"Deux adresses, une même ville","auteur":"Récit imaginé pour l’exercice.","blocs":["Camille habite au vingtième étage d’une tour, dans le quartier d’affaires d’une grande ville du Brésil. Son père travaille dans une banque et la famille voyage chaque été.","À vingt minutes de là, Davi vit dans un bidonville bâti sur une colline. Il n’y a pas d’eau courante dans sa rue et l’école la plus proche est loin."]}],"questions":[{"enonce":"Lis sur le graphique l’IDH du Brésil.","aide":"Repère la barre du Brésil et lis sa hauteur sur l’axe de gauche.","type":"nombre"},{"enonce":"Quel écart d’IDH y a-t-il entre la Norvège et le Niger ?","aide":"Soustrais l’IDH du Niger à celui de la Norvège.","type":"nombre"},{"enonce":"Touche le mot du récit qui désigne un quartier pauvre et précaire.","aide":"Cherche l’endroit où vit Davi.","type":"zone","document":"recit","multiple":false},{"enonce":"Que montre le récit à propos d’un pays émergent comme le Brésil ?","aide":"Compare la vie de Camille et celle de Davi.","type":"choix","options":[{"id":"a","texte":"Il a le même niveau de vie dans toutes les régions"},{"id":"b","texte":"Il compte uniquement des quartiers d’affaires et des tours"},{"id":"c","texte":"Il peut avoir de fortes inégalités à l’intérieur même d’une ville"},{"id":"d","texte":"Il n’a plus aucun habitant pauvre dans ses grandes villes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.75,"tolerance":0.01},"affichage":"0,75","explication":"L’IDH du Brésil est d’environ **0,75** : un pays émergent, entre les pays développés et les pays les moins avancés."},{"cle":{"type":"nombre","valeur":0.57,"tolerance":0.005},"affichage":"0,57","explication":"0,96 − 0,39 = **0,57** : la Norvège dépasse 0,95, alors que plusieurs pays d’Afrique subsaharienne restent sous 0,45."},{"cle":{"type":"zone","ids":["m40"]},"explication":"Davi vit dans un **bidonville**, à côté d’un quartier d’affaires : les inégalités existent à l’intérieur d’une même ville."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les pays **émergents** connaissent une croissance rapide mais de **fortes inégalités internes** : bidonvilles et quartiers d’affaires peuvent se côtoyer."}]$ex$::jsonb),
  ('0afccf60-b288-5dbc-a319-d50cfb5c2997'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La pauvreté recule : comment ?","competence":"analyser-document","situation":"Samia lit un graphique sur la part de la population mondiale qui vit en pauvreté extrême, puis l’histoire de Fatou, dans un village d’un pays très pauvre. Elle cherche ce qui aide à réduire les écarts.","documents":[{"id":"pauvrete","type":"graphique","forme":"barres","titre":"Part de la population mondiale en pauvreté extrême","source":"Ordres de grandeur arrondis, d’après la Banque mondiale.","categories":["1990","2000","2010","2019"],"series":[{"nom":"Pauvreté extrême","valeurs":[36,29,16,9],"teinte":"ambre"}],"axeY":{"titre":"Part de la population mondiale","unite":"%","min":0,"max":40,"pas":10},"axeX":{"titre":"Année"},"valeurs":false},{"id":"fatou","type":"texte","genre":"article","titre":"Fatou et sa famille","auteur":"Récit imaginé pour l’exercice.","blocs":["Fatou vit dans un village d’un pays très pauvre. Grâce à un microcrédit, elle a emprunté une petite somme pour acheter un moulin à grain.","Sa fille Awa va à l’école : elle sera la première de la famille à savoir lire.","Son frère travaille loin du pays et lui envoie de l’argent chaque mois."]}],"questions":[{"enonce":"De combien de points la part de la population mondiale en pauvreté extrême a-t-elle baissé entre 1990 et 2019 ?","aide":"Lis la première et la dernière barre, puis soustrais.","type":"nombre","unite":"points"},{"enonce":"Touche la première année où cette part passe **sous 20 %**.","aide":"Lis les barres de gauche à droite et arrête-toi à la première qui est sous la graduation 20.","type":"zone","document":"pauvrete","multiple":false},{"enonce":"En 2019, environ 9 % des 8 milliards d’humains vivent en pauvreté extrême. Combien cela fait-il de millions de personnes ?","aide":"8 milliards = 8 000 millions. Calcule 9 % de 8 000.","type":"nombre","unite":"millions"},{"enonce":"Associe chaque moment de l’histoire de Fatou au levier qui réduit les écarts.","aide":"Lis les trois paragraphes : chacun montre un levier différent.","type":"association","gauche":[{"id":"g0","texte":"Fatou emprunte une petite somme pour son moulin"},{"id":"g1","texte":"Awa va à l’école"},{"id":"g2","texte":"Le frère envoie de l’argent chaque mois"}],"droite":[{"id":"d0","texte":"Un microcrédit"},{"id":"d1","texte":"Un transfert de migrant"},{"id":"d2","texte":"La scolarisation"}]},{"enonce":"Que conclure du graphique et du récit ?","aide":"Regarde la tendance des barres, puis le chiffre de 2019.","type":"choix","options":[{"id":"a","texte":"L’extrême pauvreté a reculé mais reste forte : il faut agir encore"},{"id":"b","texte":"L’extrême pauvreté augmente de plus en plus depuis l’année 1990"},{"id":"c","texte":"L’extrême pauvreté a disparu du monde entier depuis l’année 2019"},{"id":"d","texte":"L’extrême pauvreté ne recule que dans les pays les plus riches"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":27,"tolerance":0},"affichage":"27 points","explication":"36 − 9 = **27** points : l’extrême pauvreté a fortement reculé en trente ans."},{"cle":{"type":"zone","ids":["k2"]},"explication":"En **2010**, la part est de 16 % : c’est la première fois qu’elle passe sous 20 %."},{"cle":{"type":"nombre","valeur":720,"tolerance":0},"affichage":"720 millions","explication":"9 % de 8 000 millions = 8 000 × 0,09 = **720 millions** : un chiffre voisin des 700 millions du cours, donc encore très élevé."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Microcrédits, scolarisation et **transferts** des migrants (supérieurs à l’aide publique au développement) réduisent les écarts."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les inégalités demeurent, mais le monde de 2020 n’est pas celui de 1990 : les progrès sont réels, il reste environ **700 millions** de personnes en pauvreté extrême."}]$ex$::jsonb),
  ('0465db80-dd5d-5ee7-81ab-7be62edcfd41'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un tiers de la nourriture qui n’est pas mangée","competence":"lire-graphique","situation":"Au collège, Hugo apprend que la planète produit assez de nourriture pour tous, et pourtant que des gens ont faim. Il regarde ce que devient la nourriture produite.","documents":[{"id":"nourriture","type":"graphique","forme":"secteurs","titre":"Que devient la nourriture produite ?","source":"Chiffres arrondis : environ un tiers est perdu ou gaspillé.","categories":["Mangée","Perdue ou gaspillée"],"series":[{"nom":"Nourriture produite","valeurs":[67,33]}]}],"questions":[{"enonce":"Touche la part de nourriture qui **ne nourrit personne**.","aide":"Cherche l’étiquette qui parle de perte ou de gaspillage.","type":"zone","document":"nourriture","multiple":false},{"enonce":"Sur 300 millions de tonnes produites (chiffre imaginé), combien de millions de tonnes sont perdues ou gaspillées ? Arrondis à l’unité.","aide":"Un tiers de 300, c’est 300 ÷ 3.","type":"nombre","unite":"Mt"},{"enonce":"Que peut-on faire pour nourrir plus d’humains sans produire davantage ?","aide":"Que devient le tiers de nourriture du graphique ?","type":"choix","options":[{"id":"a","texte":"Réduire le gaspillage et les pertes"},{"id":"b","texte":"Cultiver toujours plus de terres"},{"id":"c","texte":"Augmenter la consommation de viande"},{"id":"d","texte":"Importer moins de nourriture"}],"multiple":false}]}$ex$::jsonb,
