   $ex$[{"cle":{"type":"zone","ids":["r4c1"]},"explication":"La récolte de l’exploitation A est destinée à **la famille** : c’est une agriculture vivrière."},{"cle":{"type":"nombre","valeur":1200,"tolerance":0},"affichage":"1200 tonnes","explication":"150 ha × 8 t par ha = **1 200 tonnes**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec peu de moyens et seulement la pluie, l’exploitation A est **très exposée aux aléas** : une sécheresse peut priver la famille de nourriture."},{"cle":{"type":"trous","trous":[["eau"],["intrants","intrant"]]},"affichage":"eau · intrants","explication":"Irrigation et engrais, c’est de l’**eau** et des **intrants** : un prix à payer pour de forts rendements."}]$ex$::jsonb),
  ('0465db80-dd5d-5ee7-81ab-7be62edcfd41'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Du maïs qui pourrit, des familles qui ont faim","competence":"analyser-document","situation":"Dans un pays imaginé d’Afrique de l’Est, la récolte est bonne et pourtant des familles ne mangent pas à leur faim. Anna lit un article et un tableau pour chercher la vraie cause.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Une bonne récolte, des greniers vides","auteur":"Article imaginé pour l’exercice.","blocs":["Dans une région d’Afrique de l’Est, la récolte de maïs a été bonne cette année. Mais faute de routes praticables et de silos pour la stocker, une grande partie du maïs pourrit au bord des champs.","À trois cents kilomètres de là, dans une ville du même pays, des familles ne peuvent plus acheter de maïs : les prix ont flambé."]},{"id":"cereales","type":"tableau","titre":"Les céréales du pays","source":"Chiffres imaginés pour l’exercice.","colonnes":["Céréales du pays","Millions de tonnes"],"lignes":[["Récolte de l’année",12],["Besoins de la population",10],["Pertes après la récolte",3]],"enteteLignes":true}],"questions":[{"enonce":"Combien de millions de tonnes de céréales restent disponibles après les pertes ?","aide":"Récolte − pertes.","type":"nombre","unite":"Mt"},{"enonce":"Que dit le tableau sur la production du pays ?","aide":"Compare d’abord la récolte aux besoins, puis retire les pertes.","type":"choix","options":[{"id":"a","texte":"Elle est deux fois plus grande que les besoins de la population"},{"id":"b","texte":"Elle suffirait aux besoins, mais les pertes la font passer sous eux"},{"id":"c","texte":"Elle est très insuffisante : le pays doit tout importer du monde"},{"id":"d","texte":"Elle est inférieure aux pertes enregistrées après la récolte"}],"multiple":false},{"enonce":"Touche les **deux mots** qui expliquent pourquoi une partie de la récolte est perdue.","aide":"Cherche ce qui manque pour transporter et pour conserver le maïs.","type":"zone","document":"article","multiple":true},{"enonce":"Quel pourcentage de la récolte est perdu ?","aide":"Divise les pertes par la récolte, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Quelle piste aiderait le plus ce pays à assurer la sécurité alimentaire ?","aide":"Reviens à la cause des pertes dans l’article.","type":"choix","options":[{"id":"a","texte":"Réduire encore la surface cultivée"},{"id":"b","texte":"Faire monter les prix du maïs"},{"id":"c","texte":"Améliorer le stockage et les transports"},{"id":"d","texte":"Importer toutes les céréales du monde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 Mt","explication":"12 − 3 = **9** millions de tonnes disponibles, contre 10 de besoins : il en manque 1."},{"cle":{"type":"choix","ids":["b"]},"explication":"La récolte (12) dépasse les besoins (10), mais après **3 millions de tonnes de pertes** il reste 9 : trop peu. Le problème n’est pas seulement la quantité produite."},{"cle":{"type":"zone","ids":["m20","m24"]},"explication":"Sans **routes** pour le transporter ni **silos** pour le stocker, le maïs se perd : c’est un problème d’accès, pas de production."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 %","explication":"3 ÷ 12 = 0,25, soit **25 %** : un quart de la récolte est perdu."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Stockage et transports** font partie des pistes pour assurer la sécurité alimentaire : l’accès de tous, à tout moment, à une nourriture suffisante et saine."}]$ex$::jsonb),
