   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le pays **C** n’a que 800 m³ par habitant et par an : c’est le plus mal pourvu."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c2","i5":"c2"}},"explication":"**A** (4 800) et **D** (2 100) dépassent 1 700 ; **B** (1 400) et **E** (1 650) sont en stress hydrique ; **C** (800) et **F** (950) sont sous 1 000 : pénurie."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 fois","explication":"4 800 ÷ 800 = **6** : l’eau est très inégalement répartie."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 m³","explication":"1 700 − 1 650 = **50** m³ : le pays E est tout juste en stress hydrique."}]$ex$::jsonb),
