   $ex${"titre":"Fleuves partagés et eau cachée dans nos produits","competence":"analyser-document","situation":"Samir étudie deux façons dont l’eau devient un enjeu : des fleuves que plusieurs pays se partagent au Proche-Orient et en Égypte, et l’eau « cachée » dans les produits qu’on échange.","documents":[{"id":"carte","type":"carte","titre":"Quelques fleuves du Proche-Orient","fond":"mediterranee","cadrage":[25,24,50,38],"fleuves":["nil","tigre","euphrate","jourdain"],"source":"Fleuves cités dans le cours.","lieux":[{"id":"z1","lieu":"le-caire","nom":"Le Caire","symbole":"point","teinte":"violet"},{"id":"z2","lieu":"bagdad","nom":"Bagdad","symbole":"point","teinte":"violet"},{"id":"z3","lieu":"jerusalem","nom":"Jérusalem","symbole":"point","teinte":"violet"},{"id":"z4","lieu":"damas","nom":"Damas","symbole":"point","teinte":"violet"}]},{"id":"virtuelle","type":"tableau","titre":"L’eau virtuelle de quelques produits","source":"Chiffres arrondis (cours).","colonnes":["Produit","Eau nécessaire pour le produire"],"lignes":[["1 kg de bœuf","15 000 litres"],["1 tee-shirt en coton","2 700 litres"],["1 tasse de café","140 litres"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ville située au bord du **Tigre**.","aide":"Le Tigre et l’Euphrate coulent côte à côte vers le golfe Persique : repère le fleuve le plus à l’est.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville située au bord du **Nil**.","aide":"Le Nil coule du sud vers le nord, vers la Méditerranée.","type":"zone","document":"carte","multiple":false},{"enonce":"Pourquoi un fleuve partagé entre plusieurs pays peut-il provoquer des conflits ?","aide":"Que devient l’eau que le premier pays prélève, pour le pays situé en aval ?","type":"choix","options":[{"id":"a","texte":"Un fleuve ne contient jamais assez d’eau pour un seul pays"},{"id":"b","texte":"Chaque pays veut garder sa part, et l’eau prélevée en amont manque en aval"},{"id":"c","texte":"Les pays riverains n’ont jamais besoin d’eau pour leurs cultures"},{"id":"d","texte":"Les fleuves coulent toujours dans des sens différents selon les pays"}],"multiple":false},{"enonce":"Un pays importe 1 000 kg de bœuf. Combien de millions de litres d’eau virtuelle cela représente-t-il ?","aide":"1 000 kg × 15 000 litres, puis exprime le résultat en millions.","type":"nombre","unite":"millions de L"},{"enonce":"Pourquoi importer des produits à forte eau virtuelle peut-il aider un pays en pénurie d’eau ?","aide":"Relis le tableau : de quoi le bœuf a-t-il besoin pour être produit ?","type":"choix","options":[{"id":"a","texte":"Il remplit directement ses nappes d’eau souterraines"},{"id":"b","texte":"Il évite d’utiliser sa propre eau pour les produire"},{"id":"c","texte":"Il supprime tous ses besoins en eau potable"},{"id":"d","texte":"Il fait tomber plus de pluie sur son territoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Bagdad** est située sur le Tigre. Le Tigre et l’Euphrate sont deux fleuves partagés entre plusieurs pays."},{"cle":{"type":"zone","ids":["z1"]},"explication":"**Le Caire** est sur le Nil, fleuve dont les eaux sont partagées entre plusieurs pays riverains."},{"cle":{"type":"choix","ids":["b"]},"explication":"Nil, Jourdain, Tigre et Euphrate sont des sources de **conflits entre pays riverains** : ce que l’un prélève en amont manque à l’autre en aval."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 millions de L","explication":"1 000 × 15 000 = 15 000 000 litres, soit **15 millions** de litres : importer un produit, c’est importer l’eau qui a servi à le faire."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’eau virtuelle est celle qui a servi à **produire** le bien : un pays qui l’importe économise l’eau de ses propres nappes et fleuves."}]$ex$::jsonb),
  ('cae7a8b6-8739-5d2d-b9a3-5893ff36c18e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"D’où vient l’énergie du monde ?","competence":"lire-graphique","situation":"Axel veut savoir d’où vient l’énergie que consomme l’humanité. Il lit un graphique en secteurs qui montre le mix énergétique mondial.","documents":[{"id":"mix","type":"graphique","forme":"secteurs","titre":"Le mix énergétique mondial","source":"Chiffres arrondis (ordre de grandeur).","categories":["Pétrole","Charbon","Gaz naturel","Nucléaire","Renouvelables"],"series":[{"nom":"Part du mix","valeurs":[31,27,23,4,15]}]}],"questions":[{"enonce":"Touche la source d’énergie la plus utilisée dans le monde.","aide":"Cherche le plus grand secteur.","type":"zone","document":"mix","multiple":false},{"enonce":"Additionne le pétrole, le charbon et le gaz naturel : quelle part du mix représentent ces trois énergies fossiles ?","aide":"31 + 27 + 23.","type":"nombre","unite":"%"},{"enonce":"Que conclure du graphique ?","aide":"Reprends le résultat de ton addition.","type":"choix","options":[{"id":"a","texte":"Les énergies fossiles fournissent environ quatre cinquièmes de l’énergie"},{"id":"b","texte":"Les énergies renouvelables fournissent plus de la moitié de l’énergie"},{"id":"c","texte":"Le charbon a disparu du mix énergétique"},{"id":"d","texte":"Le nucléaire est la première source d’énergie mondiale"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Le **pétrole** est la première source d’énergie, avec environ 31 % du mix."},{"cle":{"type":"nombre","valeur":81,"tolerance":1},"affichage":"81 %","explication":"31 + 27 + 23 = **81 %** : les fossiles pèsent encore environ 80 % du mix mondial."},{"cle":{"type":"choix","ids":["a"]},"explication":"Environ 80 % de l’énergie vient encore des fossiles : leur combustion émet du CO₂, première cause du réchauffement."}]$ex$::jsonb),
  ('cae7a8b6-8739-5d2d-b9a3-5893ff36c18e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Nina et Karim débattent de l’énergie","competence":"analyser-texte","situation":"Deux élèves échangent des messages à propos de l’énergie du futur. Leur discussion fait apparaître les atouts et les limites de chaque source.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Une discussion sur l’énergie","source":"Dialogue imaginé pour l’exercice.","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Karim","texte":"Pour moi, le nucléaire, c’est l’avenir : presque pas de CO₂ !"},{"qui":"Nina","texte":"Oui, mais il y a les déchets radioactifs et le risque d’accident : Tchernobyl en 1986, Fukushima en 2011."},{"qui":"Karim","texte":"Alors le solaire et l’éolien !"},{"qui":"Nina","texte":"Ils sont intermittents : pas de soleil la nuit, pas de vent certains jours."},{"qui":"Karim","texte":"Donc aucune énergie n’est parfaite ?"},{"qui":"Nina","texte":"Non. La première énergie propre est celle qu’on ne consomme pas !"}]}],"questions":[{"enonce":"Touche les **deux mots** de Nina qui donnent les problèmes du nucléaire.","aide":"Cherche ce qui reste après l’usage du combustible et ce qui peut arriver en cas de panne grave.","type":"zone","document":"sms","multiple":true},{"enonce":"Associe chaque énergie à son principal problème.","aide":"Un des problèmes figure dans la discussion pour chaque énergie sauf une : celle qu’on brûle.","type":"association","gauche":[{"id":"g0","texte":"Le nucléaire"},{"id":"g1","texte":"Le solaire et l’éolien"},{"id":"g2","texte":"Le charbon, le pétrole et le gaz"}],"droite":[{"id":"d0","texte":"Leur combustion émet du CO₂"},{"id":"d1","texte":"L’intermittence"},{"id":"d2","texte":"Les déchets et le risque d’accident"}]},{"enonce":"Combien d’années séparent les deux accidents nucléaires cités par Nina ?","aide":"Soustrais l’année de Tchernobyl à celle de Fukushima.","type":"nombre","unite":"ans"},{"enonce":"Que veut dire Nina par « la première énergie propre est celle qu’on ne consomme pas » ?","aide":"Pense au premier levier de la transition énergétique.","type":"choix","options":[{"id":"a","texte":"Il faut brûler plus de charbon pour se chauffer"},{"id":"b","texte":"Il faut d’abord consommer moins d’énergie"},{"id":"c","texte":"Il faut construire uniquement des centrales nucléaires"},{"id":"d","texte":"Il faut arrêter toute production d’électricité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m24"]},"explication":"Les **déchets** radioactifs et le risque d’**accident** sont les principaux inconvénients du nucléaire."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Le nucléaire pose le problème des **déchets** et des accidents, les renouvelables sont **intermittentes**, les fossiles émettent du **CO₂**."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 ans","explication":"2011 − 1986 = **25** ans entre Tchernobyl et Fukushima."},{"cle":{"type":"choix","ids":["b"]},"explication":"La **sobriété** est le premier levier : même une énergie renouvelable n’est jamais sans impact."}]$ex$::jsonb),
  ('cae7a8b6-8739-5d2d-b9a3-5893ff36c18e'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un lycée réduit sa consommation d’énergie","competence":"analyser-document","situation":"Le lycée de Léna veut réduire sa facture d’énergie. Un plan en six actions est affiché dans le hall, et un tableau donne l’électricité prise sur le réseau à chaque étape.","documents":[{"id":"plan","type":"fiche","modele":"affiche","entete":"Plan énergie du lycée","sousTitre":"Six actions pour consommer moins","lignes":[{"texte":"Éteindre les lumières des salles vides"},{"texte":"Organiser un ramassage scolaire en bus plutôt que des trajets en voiture"},{"texte":"Remplacer les vieilles ampoules par des LED"},{"texte":"Régler le chauffage avec des capteurs de présence"},{"texte":"Poser des panneaux solaires sur le toit"},{"texte":"Remplacer la chaudière au fioul par une chaudière à granulés de bois"}],"pied":"Plan imaginé pour l’exercice.","teinte":"violet"},{"id":"tab","type":"tableau","titre":"Électricité prise sur le réseau","source":"Chiffres imaginés pour l’exercice.","colonnes":["Étape","Électricité du réseau (kWh par an)"],"lignes":[["Avant le plan","100 000"],["Après la sobriété","92 000"],["Après l’efficacité","80 000"],["Après les panneaux solaires","60 000"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque action du plan dans son levier de la transition énergétique.","aide":"Sobriété : consommer moins. Efficacité : consommer mieux. Substitution : remplacer une énergie fossile par une énergie décarbonée.","type":"categories","categories":[{"id":"c0","texte":"Sobriété"},{"id":"c1","texte":"Efficacité"},{"id":"c2","texte":"Substitution"}],"items":[{"id":"i0","texte":"Panneaux solaires sur le toit"},{"id":"i1","texte":"Remplacer les vieilles ampoules par des LED"},{"id":"i2","texte":"Chauffage réglé par des capteurs de présence"},{"id":"i3","texte":"Ramassage scolaire en bus plutôt qu’en voiture"},{"id":"i4","texte":"Éteindre les lumières des salles vides"},{"id":"i5","texte":"Chaudière à granulés de bois à la place du fioul"}]},{"enonce":"Quelle quantité d’électricité le plan permet-il d’économiser en tout ?","aide":"Compare la ligne « Avant le plan » à la dernière ligne.","type":"nombre","unite":"kWh par an"},{"enonce":"Quelle étape fait baisser le plus l’électricité prise sur le réseau ?","aide":"Calcule la baisse à chaque étape en soustrayant deux lignes voisines.","type":"choix","options":[{"id":"a","texte":"L’efficacité (12 000 kWh en moins)"},{"id":"b","texte":"Les panneaux solaires (20 000 kWh en moins)"},{"id":"c","texte":"Aucune : toutes les étapes économisent autant"},{"id":"d","texte":"La sobriété (8 000 kWh en moins)"}],"multiple":false},{"enonce":"Dans quel ordre faut-il appliquer les trois leviers de la transition énergétique ?","aide":"Consommer moins d’abord, puis consommer mieux, puis changer de source.","type":"ordre","items":[{"id":"a","texte":"Efficacité"},{"id":"b","texte":"Sobriété"},{"id":"c","texte":"Substitution"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c2"}},"explication":"**Sobriété** : éteindre, covoiturer en bus. **Efficacité** : LED et capteurs, pour le même service avec moins d’énergie. **Substitution** : solaire et bois remplacent le fioul."},{"cle":{"type":"nombre","valeur":40000,"tolerance":0},"affichage":"40 000 kWh par an","explication":"100 000 − 60 000 = **40 000** kWh par an."},{"cle":{"type":"choix","ids":["b"]},"explication":"Sobriété : 8 000 ; efficacité : 12 000 ; panneaux solaires : **20 000** kWh. La substitution pèse le plus ici, mais il faut les trois leviers."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"**Sobriété**, puis **efficacité**, puis **substitution** : la première énergie propre est celle qu’on ne consomme pas."}]$ex$::jsonb),
  ('0aa371be-c900-5ad2-860f-cd710f11d87d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Du CO₂ au réchauffement : la chaîne","competence":"observer-schema","situation":"Sa professeure demande à Elsa de compléter la chaîne qui relie nos activités au réchauffement du climat. Il manque la dernière étape.","documents":[{"id":"chaine","type":"chaine","titre":"Une chaîne de causes","disposition":"colonne","source":"Chaîne du cours.","noeuds":[{"id":"z1","texte":"Fossiles brûlés, déforestation, agriculture"},{"id":"z2","texte":"Émissions de CO₂ et de méthane"},{"id":"z3","texte":"Effet de serre renforcé"},{"id":"z4","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Que faut-il écrire à la place du « ? »","aide":"Un effet de serre renforcé retient plus de chaleur.","type":"choix","options":[{"id":"a","texte":"Un réchauffement du climat"},{"id":"b","texte":"La disparition de l’effet de serre"},{"id":"c","texte":"Une baisse des émissions de CO₂"},{"id":"d","texte":"Un refroidissement du climat"}],"multiple":false},{"enonce":"Touche l’étape qui vient directement des **activités humaines**.","aide":"Cherche la première étape de la chaîne.","type":"zone","document":"chaine","multiple":false},{"enonce":"Un élève propose de supprimer l’effet de serre pour stopper le réchauffement. Pourquoi a-t-il tort ?","aide":"Souviens-toi : le problème n’est pas l’effet de serre lui-même.","type":"choix","options":[{"id":"a","texte":"Il est naturel et indispensable : sans lui, la Terre serait à −18 °C"},{"id":"b","texte":"Il n’existe que depuis l’invention des usines et des machines"},{"id":"c","texte":"Il ne dépend ni du CO₂ ni du méthane présents dans l’air"},{"id":"d","texte":"Il refroidit toujours la planète, même quand il se renforce"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"L’effet de serre renforcé provoque le **réchauffement** : environ +1,2 °C depuis l’ère préindustrielle."},{"cle":{"type":"zone","ids":["z1"]},"explication":"La combustion des fossiles, la déforestation et l’agriculture sont des **activités humaines** : elles sont à l’origine des émissions."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le problème est son **renforcement** par les émissions humaines, pas l’effet de serre naturel."}]$ex$::jsonb),
  ('0aa371be-c900-5ad2-860f-cd710f11d87d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Quatre régions face au changement global","competence":"lire-carte","situation":"Sur une carte du monde, Hugo repère quatre lieux qui illustrent les effets très inégaux du changement global : un delta, le Sahel, les régions polaires.","documents":[{"id":"carte","type":"carte","titre":"Des effets très inégaux","fond":"monde","reperes":true,"cadrage":[-30,0,130,75],"source":"Lieux cités ou illustrant le cours.","lieux":[{"id":"z1","lieu":"dacca","nom":"Dacca","symbole":"point","teinte":"violet"},{"id":"z2","lieu":"alexandrie","nom":"Alexandrie","symbole":"point","teinte":"violet"},{"id":"z3","lieu":"tombouctou","nom":"Tombouctou","symbole":"point","teinte":"violet"},{"id":"z4","lieu":"mourmansk","nom":"Mourmansk","symbole":"point","teinte":"violet"}]}],"questions":[{"enonce":"Touche les **deux villes** situées sur de grands deltas, densément peuplés et exposés à la montée de la mer (delta du Gange au Bangladesh, delta du Nil).","aide":"L’une est en Asie du Sud, l’autre en Afrique du Nord, au bord de la Méditerranée.","type":"zone","document":"carte","multiple":true},{"enonce":"Associe chaque région à ce qu’elle subit.","aide":"Pense à la montée de la mer, à la pluie qui manque, à la glace qui fond.","type":"association","gauche":[{"id":"g0","texte":"Les États insulaires du Pacifique"},{"id":"g1","texte":"Le Sahel"},{"id":"g2","texte":"Les régions polaires"},{"id":"g3","texte":"Les grands deltas"}],"droite":[{"id":"d0","texte":"Un réchauffement deux à trois fois plus rapide"},{"id":"d1","texte":"Densément peuplés et exposés"},{"id":"d2","texte":"Menacés de submersion"},{"id":"d3","texte":"Une sécheresse qui s’aggrave"}]},{"enonce":"Touche la ville située au **Sahel**, où la sécheresse s’aggrave.","aide":"Le Sahel est une bande qui borde le sud du Sahara, en Afrique de l’Ouest.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville située dans une **région polaire**, au nord du cercle polaire arctique.","aide":"Repère le cercle polaire arctique tracé sur la carte, puis la ville située au-dessus.","type":"zone","document":"carte","multiple":false},{"enonce":"Pourquoi parle-t-on de « justice climatique » à propos des îles du Pacifique ?","aide":"Compare la part des émissions de ces îles et ce qu’elles subissent.","type":"choix","options":[{"id":"a","texte":"Parce que ces îles décident seules des règles mondiales"},{"id":"b","texte":"Parce que ces îles émettent plus de gaz que les grands pays"},{"id":"c","texte":"Parce que ces îles n’ont aucun problème de climat"},{"id":"d","texte":"Parce que ceux qui émettent le moins subissent souvent le plus"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**Dacca** (Bangladesh) et **Alexandrie** (delta du Nil) sont dans de grands deltas, très peuplés et vulnérables."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"Les effets du changement global sont **très inégaux** selon les régions."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Tombouctou**, au Mali, est dans le Sahel, où la sécheresse s’aggrave."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**Mourmansk**, en Russie, est au nord du cercle polaire : les régions polaires se réchauffent 2 à 3 fois plus vite que la moyenne."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les pays qui émettent le **moins** subissent souvent le **plus** : c’est le cœur du problème de justice climatique."}]$ex$::jsonb),
  ('0aa371be-c900-5ad2-860f-cd710f11d87d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Atténuer ou s’adapter ? Le plan de Port-Soleil","competence":"analyser-document","situation":"La ville imaginée de Port-Soleil prépare un plan climat. Chloé trie ses actions, puis lit les propos de deux délégués réunis dans une conférence internationale.","documents":[{"id":"plan","type":"fiche","modele":"affiche","entete":"Plan climat de Port-Soleil","sousTitre":"Six actions décidées par la ville","lignes":[{"texte":"Remplacer les bus diesel par des bus électriques"},{"texte":"Construire une digue le long du littoral"},{"texte":"Replanter une forêt au nord de la ville"},{"texte":"Créer des îlots de fraîcheur avec des arbres et des fontaines"},{"texte":"Isoler les bâtiments publics pour consommer moins d’énergie"},{"texte":"Installer un système d’alerte aux cyclones"}],"pied":"Plan imaginé pour l’exercice.","teinte":"turquoise"},{"id":"delegues","type":"texte","genre":"article","titre":"À la conférence internationale","auteur":"Propos imaginés pour l’exercice.","blocs":["**Le délégué d’une île du Pacifique.** « Notre pays émet très peu de gaz à effet de serre, et pourtant la mer monte jusqu’à nos maisons. »","**La déléguée d’un grand pays industriel.** « Nous voulons agir, mais nous ne réduirons pas nos émissions les premiers : nous attendons que les autres fassent leur part. »"]}],"questions":[{"enonce":"Classe les actions du plan : atténuent-elles le changement climatique ou aident-elles à s’y adapter ?","aide":"Atténuer, c’est réduire les émissions. S’adapter, c’est vivre avec les effets déjà inévitables.","type":"categories","categories":[{"id":"c0","texte":"Atténuation"},{"id":"c1","texte":"Adaptation"}],"items":[{"id":"i0","texte":"Digue le long du littoral"},{"id":"i1","texte":"Forêt replantée au nord de la ville"},{"id":"i2","texte":"Bus électriques à la place des bus diesel"},{"id":"i3","texte":"Bâtiments publics mieux isolés"},{"id":"i4","texte":"Alerte aux cyclones"},{"id":"i5","texte":"Îlots de fraîcheur en ville"}]},{"enonce":"Que montre le propos du délégué du Pacifique ?","aide":"Compare ce que le pays émet et ce qu’il subit.","type":"choix","options":[{"id":"a","texte":"Le niveau de la mer ne dépend pas du réchauffement"},{"id":"b","texte":"Les petites îles sont les premières responsables des émissions"},{"id":"c","texte":"Les pays industriels sont les premiers touchés par la mer"},{"id":"d","texte":"Ceux qui émettent le moins subissent souvent le plus"}],"multiple":false},{"enonce":"Touche le mot qui montre que la déléguée attend l’effort des autres États.","aide":"Cherche ce que la déléguée attend des autres pays.","type":"zone","document":"delegues","multiple":false},{"enonce":"La température moyenne mondiale a augmenté d’environ 1,2 °C. Une région polaire se réchauffe au moins deux fois plus vite. De combien de °C au minimum s’est-elle réchauffée ?","aide":"Multiplie 1,2 par 2.","type":"nombre","unite":"°C"},{"enonce":"Associe chaque instance de la gouvernance mondiale à son rôle.","aide":"L’un des trois est composé de scientifiques, un autre se réunit chaque année.","type":"association","gauche":[{"id":"g0","texte":"Le GIEC"},{"id":"g1","texte":"Les COP"},{"id":"g2","texte":"L’accord de Paris (2015)"}],"droite":[{"id":"d0","texte":"La négociation annuelle"},{"id":"d1","texte":"L’engagement des États"},{"id":"d2","texte":"L’expertise scientifique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"**Atténuation** : transports, reforestation, sobriété. **Adaptation** : digues, îlots de fraîcheur, alertes. Il faut les deux."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est le cœur de la **justice climatique** : les États insulaires émettent peu mais sont menacés de submersion."},{"cle":{"type":"zone","ids":["m50"]},"explication":"Chaque État est tenté d’attendre l’effort des **autres** : c’est ce qui rend la négociation climatique difficile, car le climat est un bien commun."},{"cle":{"type":"nombre","valeur":2.4,"tolerance":0},"affichage":"2,4 °C","explication":"1,2 × 2 = **2,4 °C** au minimum : les régions polaires se réchauffent deux à trois fois plus vite."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le **GIEC** produit l’expertise, les **COP** négocient chaque année, l’**accord de Paris** engage les États."}]$ex$::jsonb),
  ('78be057d-ebc3-57b0-bb56-40a5eb2b9854'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une explosion dans le désert, un incendie près d’un quartier","competence":"analyser-texte","situation":"Alma lit deux récits d’accidents industriels imaginés. Dans les deux cas, un événement dangereux se produit, mais les conséquences sont très différentes.","documents":[{"id":"recits","type":"texte","genre":"article","titre":"Deux accidents","auteur":"Récits imaginés pour l’exercice.","blocs":["Dans le désert, à cent kilomètres de tout village, une usine de gaz explose. Personne n’est blessé.","À Valmont, une usine chimique a été construite à deux cents mètres d’un quartier où vivent trois mille habitants. Un incendie s’y déclare : il faut évacuer des centaines de personnes et plusieurs sont blessées."]}],"questions":[{"enonce":"Touche le mot qui désigne l’**événement dangereux** du premier récit.","aide":"Cherche le verbe qui dit ce qui arrive à l’usine.","type":"zone","document":"recits","multiple":false},{"enonce":"Dans lequel des deux récits y a-t-il une catastrophe ?","aide":"Une catastrophe est la réalisation d’un risque : des personnes doivent être exposées.","type":"choix","options":[{"id":"a","texte":"À Valmont, où l’incendie touche des habitants"},{"id":"b","texte":"Dans aucun des deux récits"},{"id":"c","texte":"Dans les deux, car il y a une usine à chaque fois"},{"id":"d","texte":"Dans le désert, où l’usine a explosé"}],"multiple":false},{"enonce":"Touche les **deux mots** qui montrent que Valmont est vulnérable.","aide":"La vulnérabilité, c’est ce qui est exposé : cherche qui vit près de l’usine.","type":"zone","document":"recits","multiple":true},{"enonce":"Complète la définition du risque.","aide":"Risque = aléa × vulnérabilité.","type":"trous","segments":["Le risque est le croisement d’un ",0," et d’une ",1,"."],"banque":["vulnérabilité","aléa","catastrophe","prévention"]}]}$ex$::jsonb,
