  ('78be057d-ebc3-57b0-bb56-40a5eb2b9854'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une chronologie des catastrophes technologiques","competence":"se-reperer-temps","situation":"Pour son exposé, Noé place sur une frise six catastrophes technologiques citées dans son cours. Il veut ensuite les classer par type.","documents":[{"id":"frise","type":"frise","titre":"Six catastrophes de 1980 à 2020","source":"Dates du cours.","debut":1980,"fin":2020,"pas":5,"evenements":[{"id":"z1","date":1984,"nom":"Bhopal"},{"id":"z2","date":1986,"nom":"Tchernobyl"},{"id":"z3","date":1999,"nom":"Erika"},{"id":"z4","date":2001,"nom":"AZF"},{"id":"z5","date":2011,"nom":"Fukushima"},{"id":"z6","date":2019,"nom":"Lubrizol"}]}],"questions":[{"enonce":"Touche la catastrophe qui mêle **risque naturel et risque technologique**.","aide":"Un séisme et un tsunami ont déclenché l’accident d’une centrale nucléaire.","type":"zone","document":"frise","multiple":false},{"enonce":"Associe chaque catastrophe à sa nature.","aide":"Un nom de navire évoque une marée noire ; un nom de centrale, le nucléaire.","type":"association","gauche":[{"id":"g0","texte":"Bhopal (1984)"},{"id":"g1","texte":"Tchernobyl (1986)"},{"id":"g2","texte":"Erika (1999)"}],"droite":[{"id":"d0","texte":"Marée noire"},{"id":"d1","texte":"Accident nucléaire"},{"id":"d2","texte":"Catastrophe industrielle en Inde"}]},{"enonce":"Combien d’années séparent l’explosion d’AZF de l’incendie de Lubrizol ?","aide":"Lis les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Qu’ont en commun AZF et Lubrizol ?","aide":"AZF a frappé Toulouse et Lubrizol, Rouen.","type":"choix","options":[{"id":"a","texte":"Deux accidents industriels français, près de grandes villes"},{"id":"b","texte":"Deux catastrophes survenues en Inde"},{"id":"c","texte":"Deux marées noires survenues sur les côtes françaises"},{"id":"d","texte":"Deux accidents nucléaires survenus en France"}],"multiple":false}]}$ex$::jsonb,
