  ('78be057d-ebc3-57b0-bb56-40a5eb2b9854'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Valmont réduit sa vulnérabilité","competence":"analyser-document","situation":"Après un incendie, le maire d’une commune imaginée présente ce qui a été fait autour de l’usine. Rémi lit son rapport et situe sur une carte deux accidents réels en France.","documents":[{"id":"carte","type":"carte","titre":"Deux accidents industriels en France","fond":"europe","frontieres":true,"cadrage":[-6,41,10,52],"source":"Accidents cités dans le cours.","lieux":[{"id":"z1","lieu":"toulouse","nom":"Toulouse","symbole":"point","teinte":"violet"},{"id":"z2","lieu":"rouen","nom":"Rouen","symbole":"point","teinte":"violet"}]},{"id":"rapport","type":"texte","genre":"article","titre":"Le rapport du maire","auteur":"Rapport imaginé pour l’exercice.","blocs":["Nous avons dressé la carte des zones exposées autour de l’usine.","Les contrôles et les normes ont été renforcés, comme l’exige la directive européenne Seveso.","Le plan de prévention des risques technologiques interdit de construire de nouvelles maisons à moins de trois cents mètres de l’usine.","Chaque année, un exercice d’évacuation est organisé dans l’école voisine et les sirènes sont testées."]}],"questions":[{"enonce":"Touche la ville où l’usine **AZF** a explosé en 2001.","aide":"AZF est une explosion célèbre dans le sud-ouest de la France.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville où l’usine **Lubrizol** a brûlé en 2019.","aide":"Cherche une ville normande, traversée par la Seine.","type":"zone","document":"carte","multiple":false},{"enonce":"Associe chaque mesure du rapport à l’action de prévention qu’elle illustre.","aide":"Reprends les quatre paragraphes du rapport dans l’ordre.","type":"association","gauche":[{"id":"g0","texte":"Dresser la carte des zones exposées"},{"id":"g1","texte":"Appliquer la directive Seveso et renforcer les contrôles"},{"id":"g2","texte":"Interdire de nouvelles maisons près de l’usine"},{"id":"g3","texte":"Organiser un exercice d’évacuation"}],"droite":[{"id":"d0","texte":"Aménager"},{"id":"d1","texte":"Réglementer"},{"id":"d2","texte":"Informer et former"},{"id":"d3","texte":"Connaître"}]},{"enonce":"Le maire peut-il supprimer l’aléa industriel autour de l’usine ?","aide":"Relis le rapport : les mesures portent-elles sur l’usine ou sur ce qui l’entoure ?","type":"choix","options":[{"id":"a","texte":"Non : on réduit la vulnérabilité en éloignant les habitations"},{"id":"b","texte":"Oui : il suffit d’interdire toute activité industrielle"},{"id":"c","texte":"Oui : un exercice d’évacuation supprime le danger"},{"id":"d","texte":"Non : la prévention ne change rien au risque"}],"multiple":false}]}$ex$::jsonb,
