   $ex${"titre":"La course d’orientation du collège","competence":"calculer","situation":"Pour la course d’orientation, cinq balises sont posées sur le parcours. Le professeur a noté leur distance au départ en kilomètres et demande aux élèves de les écrire en fractions irréductibles.","documents":[{"id":"balises","type":"tableau","titre":"Distance de chaque balise au départ","colonnes":["Balise","Distance (km)"],"lignes":[["A","0,25"],["B","0,5"],["C","0,75"],["D","0,2"],["E","1,25"]],"enteteLignes":true,"source":"Parcours inventé pour l’exercice"}],"questions":[{"enonce":"Associe chaque distance à sa **fraction irréductible**.","aide":"Écris d’abord la fraction décimale ({{25/100}}, {{5/10}}…), puis simplifie.","type":"association","gauche":[{"id":"g0","texte":"0,25 km"},{"id":"g1","texte":"0,5 km"},{"id":"g2","texte":"0,75 km"},{"id":"g3","texte":"0,2 km"}],"droite":[{"id":"d0","texte":"{{1/4}}"},{"id":"d1","texte":"{{1/2}}"},{"id":"d2","texte":"{{1/5}}"},{"id":"d3","texte":"{{3/4}}"}]},{"enonce":"La balise E est à 1,25 km, soit {{125/100}} km. Quel est le **numérateur** de la fraction irréductible égale à 1,25 ?","aide":"Divise 125 et 100 par 25.","type":"nombre"},{"enonce":"Touche la balise située à {{1/2}} km du départ.","aide":"Écris {{1/2}} avec un dénominateur égal à 10, puis en décimal.","type":"zone","document":"balises","multiple":false},{"enonce":"Range les balises de la **plus proche** à la **plus lointaine** du départ.","aide":"Compare d’abord les parties entières, puis les dixièmes. Pense que 0,2 = 0,20.","type":"ordre","items":[{"id":"a","texte":"Balise C"},{"id":"b","texte":"Balise B"},{"id":"c","texte":"Balise D"},{"id":"d","texte":"Balise A"},{"id":"e","texte":"Balise E"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"{{25/100}} = {{1/4}} (on divise par 25) ; {{5/10}} = {{1/2}} ; {{75/100}} = {{3/4}} ; {{2/10}} = {{1/5}}. On simplifie en divisant haut et bas par le même nombre."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"On divise haut et bas par 25 : {{125/100}} = {{5/4}}. Le numérateur est **5**."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"{{1/2}} = {{5/10}} = 0,5 : c’est la **balise B**."},{"cle":{"type":"ordre","ids":["c","d","b","a","e"]},"explication":"0,2 < 0,25 < 0,5 < 0,75 < 1,25 : D, A, B, C, E. Pour comparer, on complète par des zéros : 0,20 est plus petit que 0,25."}]$ex$::jsonb),
  ('5e261956-9f14-5c71-af61-e6c3c4bf7470'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un tiers de pizza, est-ce 0,33 ?","competence":"raisonner","situation":"Yanis et Lina se partagent une pizza et discutent : peut-on toujours écrire une fraction avec une virgule qui s’arrête ? Aide-les à trancher.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"La discussion de Yanis et Lina","participants":[{"nom":"Yanis","emoji":"👦","cote":"gauche"},{"nom":"Lina","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Yanis","texte":"On est 3 et on partage la pizza : chacun a {{1/3}} = 0,33. Donc {{1/3}} est un nombre décimal !"},{"qui":"Lina","texte":"Si {{1/3}} valait 0,33, alors 3 × 0,33 ferait 1. Or 3 × 0,33 = 0,99."}]},{"id":"denominateurs","type":"tableau","titre":"Décomposition des dénominateurs","colonnes":["Fraction","Dénominateur en facteurs premiers"],"lignes":[["{{1/8}}","2 × 2 × 2"],["{{1/6}}","2 × 3"],["{{3/20}}","2 × 2 × 5"],["{{7/12}}","2 × 2 × 3"],["{{9/25}}","5 × 5"],["{{2/9}}","3 × 3"]],"enteteLignes":true,"source":"Fractions choisies pour l’exercice"}],"questions":[{"enonce":"Quel argument de Lina montre que Yanis se trompe ?","aide":"Si {{1/3}} = 0,33, que devrait donner 3 fois ce nombre ?","type":"choix","options":[{"id":"a","texte":"3 × 0,33 = 0,99, qui n’est pas égal à 1"},{"id":"b","texte":"Les fractions ne s’écrivent jamais avec une virgule"},{"id":"c","texte":"Une pizza ne peut pas se partager en trois parts"},{"id":"d","texte":"0,33 est trop petit pour être une fraction"}],"multiple":false},{"enonce":"Classe chaque fraction du tableau : son écriture décimale **s’arrête-t-elle** ?","aide":"Regarde la colonne de droite : un dénominateur avec un facteur autre que 2 ou 5 pose problème.","type":"categories","categories":[{"id":"c0","texte":"Écriture décimale qui s’arrête"},{"id":"c1","texte":"Écriture qui ne s’arrête pas"}],"items":[{"id":"i0","texte":"{{2/9}}"},{"id":"i1","texte":"{{7/12}}"},{"id":"i2","texte":"{{3/20}}"},{"id":"i3","texte":"{{9/25}}"},{"id":"i4","texte":"{{1/8}}"},{"id":"i5","texte":"{{1/6}}"}]},{"enonce":"Écris {{3/20}} en écriture décimale.","aide":"Multiplie le numérateur et le dénominateur par 5 pour obtenir un dénominateur 100.","type":"nombre"},{"enonce":"Écris {{13/40}} en écriture décimale.","aide":"Par quel nombre faut-il multiplier 40 pour obtenir 1 000 ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"Trois tiers font 1 entier, alors que 3 × 0,33 = **0,99**. Donc 0,33 n’est qu’une valeur approchée de {{1/3}}, dont l’écriture décimale ne s’arrête jamais (0,3333…)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"Seuls les dénominateurs qui n’ont que des facteurs **2 et 5** donnent un décimal : 8, 20 et 25. Un facteur 3 (dans 6, 12 et 9) empêche l’écriture de s’arrêter."},{"cle":{"type":"nombre","valeur":0.15,"tolerance":0},"affichage":"0,15","explication":"{{3/20}} = {{15/100}} = **0,15** : on multiplie haut et bas par 5 pour avoir une fraction décimale."},{"cle":{"type":"nombre","valeur":0.325,"tolerance":0},"affichage":"0,325","explication":"40 × 25 = 1 000, donc {{13/40}} = {{325/1000}} = **0,325**."}]$ex$::jsonb),
