   $ex${"titre":"Le chocolat chaud de Karim","competence":"raisonner","situation":"Karim prépare du chocolat chaud pour toute la classe. Sa recette est écrite en fractions de litre, et il aimerait tout convertir en décimaux pour utiliser son verre doseur.","documents":[{"id":"recette","type":"fiche","modele":"recette","entete":"Chocolat chaud de la classe","sousTitre":"Pour toute la classe","emoji":"☕","lignes":[{"texte":"Lait","valeur":"{{3/5}} L","id":"z1"},{"texte":"Crème","valeur":"{{1/4}} L","id":"z2"},{"texte":"Sirop de chocolat","valeur":"{{7/8}} L","id":"z3"}],"pied":"Recette inventée pour l’exercice","teinte":"brun"},{"id":"verre","type":"tableau","titre":"Les graduations du verre doseur de Karim","colonnes":["Graduation","Écriture"],"lignes":[["Plus petite division","0,001 L"],["Division utilisée","Millièmes de litre"]],"enteteLignes":true,"source":"Verre doseur imaginaire"}],"questions":[{"enonce":"Écris chaque fraction de la recette (et {{1/25}}) sous forme d’une **fraction décimale**.","aide":"Cherche par quel nombre multiplier le dénominateur pour obtenir 10, 100 ou 1 000.","type":"association","gauche":[{"id":"g0","texte":"{{1/4}}"},{"id":"g1","texte":"{{3/5}}"},{"id":"g2","texte":"{{7/8}}"},{"id":"g3","texte":"{{1/25}}"}],"droite":[{"id":"d0","texte":"{{6/10}}"},{"id":"d1","texte":"{{25/100}}"},{"id":"d2","texte":"{{4/100}}"},{"id":"d3","texte":"{{875/1000}}"}]},{"enonce":"Quelle quantité de liquide font le lait et la crème ensemble ? Écris-la en décimal.","aide":"Convertis {{3/5}} et {{1/4}} en centièmes, puis additionne.","type":"nombre","unite":"L"},{"enonce":"Classe ces fractions : peuvent-elles s’écrire comme **fraction décimale** ?","aide":"Regarde les facteurs premiers du dénominateur : seuls 2 et 5 sont acceptés.","type":"categories","categories":[{"id":"c0","texte":"Oui, c’est un décimal"},{"id":"c1","texte":"Non, jamais"}],"items":[{"id":"i0","texte":"{{3/8}}"},{"id":"i1","texte":"{{4/5}}"},{"id":"i2","texte":"{{1/3}}"},{"id":"i3","texte":"{{5/6}}"},{"id":"i4","texte":"{{2/7}}"},{"id":"i5","texte":"{{1/4}}"}]},{"enonce":"Karim veut ajouter {{1/3}} L d’eau et l’écrire exactement avec son verre doseur gradué en millièmes. Que peut-on dire ?","aide":"Pense à 3 × 0,333 : fait-on bien 1 ?","type":"choix","options":[{"id":"a","texte":"Impossible : 0,333 n’est qu’une valeur approchée de {{1/3}}"},{"id":"b","texte":"Impossible : le verre ne sait pas mesurer les fractions"},{"id":"c","texte":"C’est possible : {{1/3}} = 0,333 exactement"},{"id":"d","texte":"C’est possible : il suffit d’ajouter un 3 de plus après la virgule"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"4 × 25 = 100 ; 5 × 2 = 10 ; 8 × 125 = 1 000 ; 25 × 4 = 100. On multiplie haut et bas par le même nombre : {{1/4}} = {{25/100}}, {{3/5}} = {{6/10}}, {{7/8}} = {{875/1000}}, {{1/25}} = {{4/100}}."},{"cle":{"type":"nombre","valeur":0.85,"tolerance":0},"affichage":"0,85 L","explication":"{{3/5}} = 0,6 et {{1/4}} = 0,25 : 0,60 + 0,25 = **0,85 L**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1","i5":"c0"}},"explication":"4, 8 et 5 n’ont que des facteurs 2 et 5 : on peut les ramener à 10, 100 ou 1 000. Les dénominateurs 3, 7 et 6 (qui contient 3) ne s’y ramènent jamais."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le dénominateur 3 n’est pas une puissance de 10 et ne s’y ramène pas : {{1/3}} = 0,3333… ne s’arrête jamais. Le verre ne peut donner que **0,333 L, une approximation**."}]$ex$::jsonb),
