   $ex$[{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 sachets","explication":"5 × 9 = 45 et 5 × 10 = 50 dépasse 47 : le quotient est **9**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 bonbons","explication":"47 − 45 = **2** : le reste est toujours plus petit que le diviseur 5."},{"cle":{"type":"trous","trous":[["9"],["2"]]},"affichage":"9 · 2","explication":"a = b × q + r avec 0 ≤ r < b : 47 = 5 × **9** + **2**."}]$ex$::jsonb),
  ('b56ac3d8-82df-5d7c-87e8-d81acb14bc76'::uuid, 2, 2, 10, 35, 4,
