  ('b56ac3d8-82df-5d7c-87e8-d81acb14bc76'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Décomposer pour simplifier une fraction","competence":"raisonner","situation":"Maya veut simplifier la fraction {{84/90}}. Léo l’aide : il décompose les nombres en facteurs premiers. Ensemble, ils rangent les cartes « nombres » du club de maths.","documents":[{"id":"dialogue","type":"dialogue","modele":"sms","titre":"La discussion de Maya et Léo","participants":[{"nom":"Maya","emoji":"👧","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Maya","texte":"J’ai décomposé 90 : 2 × 45. Et voilà, c’est fini !"},{"qui":"Léo","texte":"Non, 45 n’est pas un nombre premier."}]},{"id":"cartes","type":"tableau","titre":"Cartes nombres du club","colonnes":["Carte","Nombre"],"lignes":[["A","29"],["B","51"],["C","91"],["D","37"],["E","1"]],"enteteLignes":true,"source":"Cartes inventées pour l’exercice"}],"questions":[{"enonce":"Pourquoi la décomposition « 2 × 45 » de Maya n’est-elle pas terminée ?","aide":"Dans une décomposition en facteurs premiers, chaque facteur doit n’avoir que deux diviseurs.","type":"choix","options":[{"id":"a","texte":"45 est plus grand que 2, donc on doit forcément continuer"},{"id":"b","texte":"45 est un nombre premier, mais 2 est trop petit pour le suivre"},{"id":"c","texte":"2 n’est pas un nombre premier, donc il faut le remplacer"},{"id":"d","texte":"45 a d’autres diviseurs que 1 et lui-même, par exemple 3 et 5"}],"multiple":false},{"enonce":"Complète les décompositions en facteurs premiers.","aide":"Divise par 2 tant que c’est possible, puis par 3, puis par 5, par 7…","type":"trous","segments":["60 = 2 × 2 × ",0," × 5 et 84 = 2 × 2 × 3 × ",1],"banque":["5","7","9","3"]},{"enonce":"Classe chaque carte du tableau : le nombre est-il **premier** ?","aide":"Teste les petits diviseurs : 3 et 7 sont des pièges. Et rappelle-toi le cas de 1.","type":"categories","categories":[{"id":"c0","texte":"Nombre premier"},{"id":"c1","texte":"Pas un nombre premier"}],"items":[{"id":"i0","texte":"51"},{"id":"i1","texte":"1"},{"id":"i2","texte":"37"},{"id":"i3","texte":"29"},{"id":"i4","texte":"91"}]},{"enonce":"En utilisant les décompositions de 84 et de 90, quel est le **dénominateur** de la fraction irréductible égale à {{84/90}} ?","aide":"Barre les facteurs communs en haut et en bas : 2 × 3.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"45 = 3 × 15 = 3 × 3 × 5 : il n’est pas premier, on continue. Au final 90 = **2 × 3² × 5**."},{"cle":{"type":"trous","trous":[["3"],["7"]]},"affichage":"3 · 7","explication":"60 = 2 × 2 × **3** × 5 et 84 = 2 × 2 × 3 × **7**. Chaque entier supérieur à 1 se décompose d’une seule façon en facteurs premiers."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"29 et 37 n’ont que deux diviseurs. 51 = 3 × 17 et 91 = 7 × 13. **1** n’est pas premier : il n’a qu’un seul diviseur."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15","explication":"En décomposant : 84 = 2 × 2 × 3 × 7 et 90 = 2 × 3 × 3 × 5. On barre le facteur commun 2 × 3 : il reste {{14/15}}, dont le dénominateur est **15**."}]$ex$::jsonb),
