  ('4f19059b-1a4a-5ca0-a330-575e1f934b20'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le bulletin de Thomas : pourquoi les coefficients comptent","competence":"calculer","situation":"Thomas reçoit son bulletin. Chaque matière a un coefficient, et sa mère se demande si la moyenne simple de ses quatre notes dit la même chose que la moyenne de son bulletin.","documents":[{"id":"bulletin","type":"tableau","titre":"Le bulletin du trimestre","source":"Bulletin imaginé pour l’exercice","colonnes":["Matière","Note","Coefficient"],"lignes":[["Mathématiques",15,4],["Français",12,3],["Anglais",14,2],["Sport",16,1]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est la somme des coefficients ?","aide":"Ajoute les quatre coefficients.","type":"nombre"},{"enonce":"Quelle est la somme des produits « note × coefficient » ?","aide":"Calcule 15 × 4, 12 × 3, 14 × 2 et 16 × 1, puis ajoute.","type":"nombre"},{"enonce":"Quelle est la moyenne pondérée de Thomas ?","aide":"Divise la somme des produits par la somme des coefficients, pas par 4.","type":"nombre","unite":"/20"},{"enonce":"Quelle serait la moyenne simple de ses quatre notes, sans coefficients ?","aide":"Ajoute les quatre notes, puis divise par 4.","type":"nombre","unite":"/20"},{"enonce":"Pourquoi la moyenne du bulletin (14) est-elle différente de la moyenne simple (14,25) ?","aide":"Quelle note a le plus gros coefficient, et est-elle haute ou basse ?","type":"choix","options":[{"id":"a","texte":"Les coefficients ne changent jamais le résultat final"},{"id":"b","texte":"Le bulletin arrondit toujours les notes vers le bas"},{"id":"c","texte":"La moyenne simple oublie la dernière note du tableau"},{"id":"d","texte":"Les matières à gros coefficient pèsent plus dans la moyenne"}],"multiple":false}]}$ex$::jsonb,
