ons":[{"id":"a","texte":"Remplacer MOYENNE par SOMME dans la formule"},{"id":"b","texte":"Étendre la plage jusqu’à B11 : =MOYENNE(B2:B11)"},{"id":"c","texte":"Taper le résultat 43 à la main dans la cellule"},{"id":"d","texte":"Ajouter des dollars : =MOYENNE($B$2:$B$10)"}],"multiple":false}]}$ex$::jsonb,
