  ('e055c662-f098-5023-a349-5df321bc83be'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les photocopies du CDI","competence":"calculer","situation":"Au CDI, le prix des photocopies est proportionnel à leur nombre. Chloé a noté quatre commandes dans un tableau, mais deux cases sont restées vides.","documents":[{"id":"copies","type":"tableau","titre":"Quatre commandes de photocopies","source":"Tarifs imaginés pour l’exercice","colonnes":["Commande","A","B","C","D"],"lignes":[["Nombre de copies",10,25,40,"?"],["Prix (€)","1,50","3,75","?","7,50"]],"enteteLignes":true}],"questions":[{"enonce":"Quel est le prix d’une seule copie, en euros ? (commande A)","aide":"Passage à l’unité : divise le prix de la commande A par son nombre de copies.","type":"nombre","unite":"€"},{"enonce":"Quel est le prix de la commande C (40 copies) ?","aide":"Multiplie le prix d’une copie par 40.","type":"nombre","unite":"€"},{"enonce":"Combien de copies contient la commande D, qui coûte 7,50 € ?","aide":"Divise 7,50 € par le prix d’une copie.","type":"nombre"},{"enonce":"Relie chaque méthode au calcul qui l’illustre dans ce tableau.","aide":"Une méthode multiplie, une autre additionne deux colonnes, une autre revient à 1 copie.","type":"association","gauche":[{"id":"g0","texte":"Passage à l’unité"},{"id":"g1","texte":"Linéarité"},{"id":"g2","texte":"Additivité"},{"id":"g3","texte":"Produit en croix"}],"droite":[{"id":"d0","texte":"10 × x = 1,50 × 40"},{"id":"d1","texte":"40 = 10 × 4, donc le prix est 1,50 × 4"},{"id":"d2","texte":"50 = 25 + 25, donc le prix est 3,75 + 3,75"},{"id":"d3","texte":"1,50 ÷ 10 = 0,15 € la copie, puis × 40"}]}]}$ex$::jsonb,
